package com.zeahrchelper;

import java.util.List;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;

/**
 * Arceuus RC agility hops. Stand/land tiles match Shortest Path
 * {@code agility_shortcuts.tsv} (BSD-2).
 */
@Getter
public enum AgilityShortcut
{
	BOULDER_49(
		new WorldPoint(1776, 3884, 0),
		new WorldPoint(1776, 3880, 0),
		49,
		false,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_BOULDER,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_BOULDER),
	EAST_52(
		new WorldPoint(1769, 3849, 0),
		new WorldPoint(1774, 3849, 0),
		52,
		true,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_BOTTOM,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_TOP),
	NORTH_69(
		new WorldPoint(1761, 3872, 0),
		new WorldPoint(1761, 3874, 0),
		69,
		true,
		34741,
		34741),
	WEST_73(
		new WorldPoint(1742, 3854, 0),
		new WorldPoint(1752, 3854, 0),
		73,
		false,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_MIDDLE,
		ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_MIDDLE);

	/** Wiki/gameval id for the 69 northern scramble. ObjectID1 is package-private. */
	public static final int NORTH_OBJECT_ID = 34741;
	static final int PATH_DRIFT_TILES = 6;

	private final WorldPoint from;
	private final WorldPoint to;
	private final int minAgility;
	private final boolean bidirectional;
	private final int forwardObjectId;
	private final int reverseObjectId;

	AgilityShortcut(
		WorldPoint from,
		WorldPoint to,
		int minAgility,
		boolean bidirectional,
		int forwardObjectId,
		int reverseObjectId)
	{
		this.from = from;
		this.to = to;
		this.minAgility = minAgility;
		this.bidirectional = bidirectional;
		this.forwardObjectId = forwardObjectId;
		this.reverseObjectId = reverseObjectId;
	}

	public static boolean hopBetween(WorldPoint a, WorldPoint b)
	{
		return match(a, b) != null;
	}

	public static Hop firstHop(List<WorldPoint> path)
	{
		return firstHop(path, null);
	}

	public static Hop firstHop(List<WorldPoint> path, WorldPoint player)
	{
		if (path == null || path.size() < 2)
		{
			return null;
		}

		int start = 0;
		if (player != null)
		{
			int best = 0;
			int bestDist = Integer.MAX_VALUE;
			for (int i = 0; i < path.size(); i++)
			{
				int dist = player.distanceTo(path.get(i));
				if (dist < bestDist)
				{
					bestDist = dist;
					best = i;
				}
			}
			if (bestDist <= PATH_DRIFT_TILES)
			{
				start = best;
			}
		}

		for (int i = start; i < path.size() - 1; i++)
		{
			WorldPoint origin = path.get(i);
			WorldPoint dest = path.get(i + 1);
			if (hopBetween(origin, dest))
			{
				return new Hop(origin, dest);
			}
		}
		return null;
	}

	public static int objectIdForHop(WorldPoint origin, WorldPoint dest)
	{
		AgilityShortcut shortcut = match(origin, dest);
		if (shortcut == null)
		{
			return -1;
		}
		if (origin.equals(shortcut.from) && dest.equals(shortcut.to))
		{
			return shortcut.forwardObjectId;
		}
		return shortcut.reverseObjectId;
	}

	public boolean enabled(int agility, RotationStep step, WorldPoint player, RcMode mode, boolean atMine)
	{
		if (agility < minAgility || player == null)
		{
			return false;
		}

		switch (this)
		{
			case NORTH_69:
				return step != RotationStep.GO_ALTAR && !craftingAtAltar(step);
			case WEST_73:
				return returningToMine(step) && isFromBloodAltar(player);
			case BOULDER_49:
				return returningToMine(step) && isFromSoulApproach(player);
			case EAST_52:
				if (player.getY() > 3875)
				{
					return false;
				}
				if (isBloodWestWalk(step, player, mode))
				{
					return false;
				}
				if (step == RotationStep.GO_ALTAR)
				{
					return atMine || player.getX() > 1768;
				}
				return true;
			default:
				return false;
		}
	}

	static boolean returningToMine(RotationStep step)
	{
		return step == RotationStep.RETURN_TO_MINE
			|| step == RotationStep.CHISEL_AND_RETURN
			|| step == RotationStep.MINE_FIRST
			|| step == RotationStep.MINE_SECOND;
	}

	static boolean craftingAtAltar(RotationStep step)
	{
		return step == RotationStep.CRAFT_FRAGMENTS
			|| step == RotationStep.CRAFT_REMAINING
			|| step == RotationStep.CHISEL_AT_ALTAR;
	}

	static boolean isFromBloodAltar(WorldPoint player)
	{
		return player.getX() < 1743 && player.getY() < 3860;
	}

	static boolean isFromSoulApproach(WorldPoint player)
	{
		// North of the boulder (including the 1776,3884 stand tile) or still east of it.
		// After the hop (y <= 3880) this is false so the mine uses 69, not a reverse jump.
		return player.getX() > 1776 || player.getY() >= 3884;
	}

	static boolean isBloodWestWalk(RotationStep step, WorldPoint player, RcMode mode)
	{
		return step == RotationStep.GO_ALTAR
			&& mode == RcMode.BLOOD
			&& player.getY() >= 3836
			&& player.getX() <= 1745;
	}

	private static AgilityShortcut match(WorldPoint a, WorldPoint b)
	{
		if (a == null || b == null)
		{
			return null;
		}
		for (AgilityShortcut shortcut : values())
		{
			if (a.equals(shortcut.from) && b.equals(shortcut.to))
			{
				return shortcut;
			}
			if (shortcut.bidirectional && a.equals(shortcut.to) && b.equals(shortcut.from))
			{
				return shortcut;
			}
		}
		return null;
	}

	@Getter
	public static final class Hop
	{
		private final WorldPoint from;
		private final WorldPoint to;

		Hop(WorldPoint from, WorldPoint to)
		{
			this.from = from;
			this.to = to;
		}
	}
}

package com.zeahrchelper;

import net.runelite.api.coords.WorldPoint;

/**
 * Whether the Blood Altar can be clicked from the player's tile on the way from the Dark Altar.
 * Reach 46 is the measured client menu distance to the altar footprint.
 */
public final class BloodAltarReach
{
	static final int REACH = 46;

	enum State
	{
		NONE,
		/** Altar in scene and within reach — click it. */
		READY,
		/** Altar in scene but too far — stand on {@link ZeahRcArea#DARK_APPROACH} first. */
		STAND_THEN_CLICK,
		/** Altar not in the loaded scene — walk the normal blood corridor. */
		WALK
	}

	private BloodAltarReach()
	{
	}

	static State evaluate(RotationStep step, RcMode rune, WorldPoint tile, boolean altarInScene)
	{
		return evaluate(step, rune, tile, altarInScene, false);
	}

	/**
	 * @param altarClickCommitted true after the player has clicked the Blood Altar this step —
	 *                            keep highlighting the altar instead of the stand tile while they walk.
	 */
	static State evaluate(
		RotationStep step,
		RcMode rune,
		WorldPoint tile,
		boolean altarInScene,
		boolean altarClickCommitted)
	{
		if (rune != RcMode.BLOOD || tile == null || step != RotationStep.GO_ALTAR)
		{
			return State.NONE;
		}
		if (!altarInScene)
		{
			return State.WALK;
		}
		if (reachTo(tile) <= REACH || altarClickCommitted)
		{
			return State.READY;
		}
		return State.STAND_THEN_CLICK;
	}

	/** Chebyshev distance from a tile to the nearest tile of the Blood Altar's footprint. */
	static int reachTo(WorldPoint tile)
	{
		WorldPoint sw = ZeahRcArea.BLOOD_ALTAR_FOOTPRINT_SW;
		int max = ZeahRcArea.BLOOD_ALTAR_FOOTPRINT_SIZE - 1;
		int dx = Math.max(Math.max(sw.getX() - tile.getX(), tile.getX() - (sw.getX() + max)), 0);
		int dy = Math.max(Math.max(sw.getY() - tile.getY(), tile.getY() - (sw.getY() + max)), 0);
		return Math.max(dx, dy);
	}
}

package com.zeahrchelper;

import java.awt.Color;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

@Value
public class HelperAction
{
	RotationStep step;
	String detail;
	List<WorldPoint> path;
	TileObject highlightObject;
	WorldPoint highlightTile;
	Color color;
	/** Short canvas label on the highlight (e.g. "Stand Here", "Click Here"). */
	String worldHint;

	public static HelperAction idle()
	{
		return new HelperAction(
			RotationStep.IDLE, "Waiting…", Collections.emptyList(), null, null, Color.GRAY, null);
	}
}

package com.zeahrchelper;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Singleton
public class InventoryChecker
{
	private static final int INVENTORY_SIZE = 28;
	private static final int FRAGMENTS_PER_BLOCK = 4;
	private static final int MAX_FRAGMENTS = 111;
	private static final Pattern COUNT_MANY = Pattern.compile(
		"this stack of fragments is roughly equivalent to (\\d+) pieces? of essence",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern COUNT_ONE = Pattern.compile(
		"this stack of fragments is roughly equivalent to one piece of essence",
		Pattern.CASE_INSENSITIVE);
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6,
	};
	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6,
	};

	private final Client client;

	private int trackedFragments;
	private boolean fragmentsKnown;
	/** True once a fragment count of 0 or an explicit Check has actually been observed this session. */
	private boolean baselineConfirmed;
	/** True once an explicit Check has confirmed the current count, cleared when frags run out. */
	private boolean checkConfirmed;
	private int lastDarkBlocks = -1;

	@Inject
	InventoryChecker(Client client)
	{
		this.client = client;
	}

	public void reset()
	{
		trackedFragments = 0;
		fragmentsKnown = false;
		baselineConfirmed = false;
		checkConfirmed = false;
		lastDarkBlocks = -1;
	}

	public void onChatMessage(ChatMessage event)
	{
		String message = Text.removeTags(event.getMessage());
		if (COUNT_ONE.matcher(message).find())
		{
			trackedFragments = 1;
			fragmentsKnown = true;
			baselineConfirmed = true;
			checkConfirmed = true;
			return;
		}
		Matcher many = COUNT_MANY.matcher(message);
		if (many.find())
		{
			try
			{
				trackedFragments = Math.min(MAX_FRAGMENTS, Integer.parseInt(many.group(1)));
				fragmentsKnown = true;
				baselineConfirmed = true;
				checkConfirmed = true;
			}
			catch (NumberFormatException ignored)
			{
				// Keep the previous estimate.
			}
		}
	}

	public InventorySnapshot scan()
	{
		int dense = 0;
		int dark = 0;
		int fragmentQty = 0;
		boolean hasFragmentItem = false;
		int empty = 0;
		boolean chisel = false;
		boolean pickaxe = false;
		boolean inactiveEssence = false;
		boolean activeEssence = false;
		boolean lanternInv = false;
		int lanternId = -1;
		int bloodRunes = 0;
		int soulRunes = 0;
		boolean hasRunePouch = false;

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			empty = INVENTORY_SIZE;
		}
		else
		{
			Item[] items = inventory.getItems();
			for (int i = 0; i < INVENTORY_SIZE; i++)
			{
				Item item = i < items.length ? items[i] : null;
				if (item == null || item.getId() < 0)
				{
					empty++;
					continue;
				}

				int id = item.getId();
				int qty = Math.max(0, item.getQuantity());
				if (id == ItemID.ARCEUUS_ESSENCE_BLOCK)
				{
					dense += Math.max(1, qty);
				}
				else if (id == ItemID.ARCEUUS_ESSENCE_BLOCK_DARK)
				{
					dark += Math.max(1, qty);
				}
				else if (id == ItemID.BIGBLANKRUNE)
				{
					hasFragmentItem = true;
					fragmentQty += qty;
				}
				else if (id == ItemID.BLOODRUNE)
				{
					bloodRunes += qty;
				}
				else if (id == ItemID.SOULRUNE)
				{
					soulRunes += qty;
				}
				else if (isRunePouch(id))
				{
					hasRunePouch = true;
				}
				else if (isChisel(id))
				{
					chisel = true;
				}
				else if (id == ItemID.BLOOD_ESSENCE_INACTIVE)
				{
					inactiveEssence = true;
				}
				else if (id == ItemID.BLOOD_ESSENCE_ACTIVE)
				{
					activeEssence = true;
				}
				else if (isAbyssalLantern(id))
				{
					lanternInv = true;
					lanternId = id;
				}
				else if (isPickaxe(id))
				{
					pickaxe = true;
				}
			}
		}

		// A held pouch deposits crafted runes straight into itself instead of the inventory, so
		// bloodRunes/soulRunes must include the pouch's own contents or crafting sessions using one
		// look like they never produced any runes.
		if (hasRunePouch)
		{
			PouchRuneTotals pouchRunes = scanRunePouch();
			bloodRunes += pouchRunes.blood;
			soulRunes += pouchRunes.soul;
		}

		int widgetQty = fragmentQuantityFromWidget();
		FragmentCount fragments = resolveFragmentCount(hasFragmentItem, fragmentQty, widgetQty, dark);

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment != null)
		{
			Item shield = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
			if (shield != null && isAbyssalLantern(shield.getId()))
			{
				lanternId = shield.getId();
			}
			Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			if (weapon != null && isPickaxe(weapon.getId()))
			{
				pickaxe = true;
			}
		}

		boolean lanternEquipped = lanternId != -1 && equipmentHasLantern(equipment);

		return new InventorySnapshot(
			dense,
			dark,
			fragments.quantity,
			empty,
			chisel,
			pickaxe,
			inactiveEssence,
			activeEssence,
			lanternEquipped,
			lanternInv,
			lanternId,
			fragments.known,
			hasFragmentItem,
			bloodRunes,
			soulRunes,
			checkConfirmed);
	}

	private FragmentCount resolveFragmentCount(
		boolean hasFragmentItem,
		int containerQty,
		int widgetQty,
		int dark)
	{
		if (!hasFragmentItem)
		{
			trackedFragments = 0;
			fragmentsKnown = false;
			baselineConfirmed = true;
			checkConfirmed = false;
			lastDarkBlocks = dark;
			return new FragmentCount(0, true);
		}

		int visible = Math.max(containerQty, widgetQty);
		if (visible > 1)
		{
			trackedFragments = Math.min(MAX_FRAGMENTS, visible);
			fragmentsKnown = true;
			baselineConfirmed = true;
			checkConfirmed = true;
		}
		// Without a confirmed baseline (e.g. a "?" stack already held at login/relog), a dark-block
		// drop could just be catching up on fragments this session never saw gained - stay unknown
		// rather than reporting a falsely-low count until Check or a visible qty confirms the real one.
		else if (baselineConfirmed && lastDarkBlocks >= 0 && dark < lastDarkBlocks)
		{
			int gained = FRAGMENTS_PER_BLOCK * (lastDarkBlocks - dark);
			trackedFragments = fragmentsKnown
				? Math.min(MAX_FRAGMENTS, trackedFragments + gained)
				: gained;
			fragmentsKnown = true;
			// This count is built on inference again, not a fresh confirmation - a stale
			// checkConfirmed here would let a Check of a non-full stack, followed by enough
			// chiselling to cross Full on its own, wrongly break the keep-chiselling veto.
			checkConfirmed = false;
		}
		else if (!fragmentsKnown)
		{
			// Hidden qty (incl. full second inventory): presence only until Count or a watched chisel.
			trackedFragments = Math.max(1, trackedFragments);
		}
		else if (trackedFragments <= 0)
		{
			trackedFragments = Math.max(1, visible);
			fragmentsKnown = false;
		}

		lastDarkBlocks = dark;
		return new FragmentCount(trackedFragments, fragmentsKnown);
	}

	private static final class FragmentCount
	{
		private final int quantity;
		private final boolean known;

		private FragmentCount(int quantity, boolean known)
		{
			this.quantity = quantity;
			this.known = known;
		}
	}

	private int fragmentQuantityFromWidget()
	{
		Widget container = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (container == null)
		{
			return 0;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null)
		{
			return 0;
		}
		int total = 0;
		for (int i = 0; i < children.length; i++)
		{
			Widget child = children[i];
			if (child != null && child.getItemId() == ItemID.BIGBLANKRUNE)
			{
				total += Math.max(0, child.getItemQuantity());
			}
		}
		return total;
	}

	private boolean equipmentHasLantern(ItemContainer equipment)
	{
		if (equipment == null)
		{
			return false;
		}
		Item shield = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
		return shield != null && isAbyssalLantern(shield.getId());
	}

	static boolean isChisel(int id)
	{
		return id == ItemID.CHISEL || id == ItemID.JEWELLERS_CHISEL;
	}

	static boolean isRunePouch(int id)
	{
		return id == ItemID.BH_RUNE_POUCH
			|| id == ItemID.BH_RUNE_POUCH_TROUVER
			|| id == ItemID.DIVINE_RUNE_POUCH
			|| id == ItemID.DIVINE_RUNE_POUCH_TROUVER;
	}

	/**
	 * Reads the rune pouch's live contents from its varbits (it has no ItemContainer of its own).
	 * The same 6 slot varbits are shared by the regular and Divine pouch; whichever is held is the
	 * one populating them, so no pouch-specific handling is needed here.
	 */
	private PouchRuneTotals scanRunePouch()
	{
		EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum == null)
		{
			return new PouchRuneTotals(0, 0);
		}

		int[] runeItemIds = new int[RUNE_POUCH_TYPE_VARBITS.length];
		int[] quantities = new int[RUNE_POUCH_QUANTITY_VARBITS.length];
		for (int i = 0; i < runeItemIds.length; i++)
		{
			int qty = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[i]);
			if (qty <= 0)
			{
				continue;
			}
			quantities[i] = qty;
			runeItemIds[i] = runeEnum.getIntValue(client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]));
		}
		return sumPouchRunes(runeItemIds, quantities);
	}

	static PouchRuneTotals sumPouchRunes(int[] runeItemIds, int[] quantities)
	{
		int blood = 0;
		int soul = 0;
		for (int i = 0; i < runeItemIds.length; i++)
		{
			int qty = i < quantities.length ? quantities[i] : 0;
			if (qty <= 0)
			{
				continue;
			}
			if (runeItemIds[i] == ItemID.BLOODRUNE)
			{
				blood += qty;
			}
			else if (runeItemIds[i] == ItemID.SOULRUNE)
			{
				soul += qty;
			}
		}
		return new PouchRuneTotals(blood, soul);
	}

	static final class PouchRuneTotals
	{
		final int blood;
		final int soul;

		PouchRuneTotals(int blood, int soul)
		{
			this.blood = blood;
			this.soul = soul;
		}
	}

	static boolean isAbyssalLantern(int id)
	{
		return id == ItemID.ABYSSAL_LANTERN
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL_BLUE
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL_RED
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL_WHITE
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL_PURPLE
			|| id == ItemID.ABYSSAL_LANTERN_NORMAL_GREEN
			|| id == ItemID.ABYSSAL_LANTERN_OAK
			|| id == ItemID.ABYSSAL_LANTERN_WILLOW
			|| id == ItemID.ABYSSAL_LANTERN_MAPLE
			|| id == ItemID.ABYSSAL_LANTERN_YEW
			|| id == ItemID.ABYSSAL_LANTERN_BLISTERWOOD
			|| id == ItemID.ABYSSAL_LANTERN_MAGIC
			|| id == ItemID.ABYSSAL_LANTERN_REDWOOD;
	}

	private boolean isPickaxe(int id)
	{
		ItemComposition def = client.getItemDefinition(id);
		if (def == null || def.getName() == null)
		{
			return false;
		}
		String name = def.getName().toLowerCase();
		return name.contains("pickaxe") || name.contains("pick axe");
	}
}

package com.zeahrchelper;

import lombok.Value;

@Value
public class InventorySnapshot
{
	int denseBlocks;
	int darkBlocks;
	int fragments;
	int emptySlots;
	boolean hasChisel;
	boolean hasPickaxe;
	boolean hasInactiveBloodEssence;
	boolean hasActiveBloodEssence;
	boolean lanternEquipped;
	boolean lanternInInventory;
	int lanternItemId;
	/** False when a fragment stack is present but the count was not watched or Count-checked. */
	boolean fragmentsKnown;
	/** True when a dark essence fragment stack is in the inventory. */
	boolean hasFragments;
	/** Inventory quantity plus any held Rune Pouch/Divine Rune Pouch quantity, combined. */
	int bloodRunes;
	/** Inventory quantity plus any held Rune Pouch/Divine Rune Pouch quantity, combined. */
	int soulRunes;
	/** True once an explicit Check has confirmed the current fragment count this trip. */
	boolean fragmentsCheckConfirmed;
}

