package com.zeahrchelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Singleton
public class RcPathRouter
{
	private static final int AT_TARGET_TILES = 1;

	private final SceneTracker sceneTracker;

	private List<WorldPoint> cachedPath = Collections.emptyList();
	private WorldPoint cachedEnd;
	private RotationStep cachedStep = RotationStep.IDLE;
	private int cachedAgility = -1;

	@Inject
	RcPathRouter(SceneTracker sceneTracker)
	{
		this.sceneTracker = sceneTracker;
	}

	void reset()
	{
		clearCache();
	}

	private void clearCache()
	{
		cachedPath = Collections.emptyList();
		cachedEnd = null;
		cachedStep = RotationStep.IDLE;
		cachedAgility = -1;
	}

	List<WorldPoint> pathTo(
		WorldView worldView,
		WorldPoint start,
		WorldPoint end,
		RotationStep step,
		int agility,
		RcMode mode,
		boolean atMine,
		boolean showPath,
		boolean keepBloodAltarLoaded)
	{
		if (!showPath || start == null || end == null || start.distanceTo(end) <= AT_TARGET_TILES)
		{
			clearCache();
			return Collections.emptyList();
		}

		if (cachedStep == step && cachedAgility == agility && end.equals(cachedEnd) && cachedPath.size() > 1)
		{
			List<WorldPoint> trimmed = trimPath(cachedPath, start);
			if (trimmed != null)
			{
				cachedPath = trimmed;
				return Pathfinder.simplify(trimmed);
			}
		}

		List<WorldPoint> path;
		if (AgilityShortcut.WEST_73.enabled(agility, step, start, mode, atMine))
		{
			path = routeViaShortcut(worldView, start, end, AgilityShortcut.WEST_73);
		}
		else if (useSoulApproach(step, start, mode, atMine))
		{
			path = waypointApproachPath(worldView, start, end, ZeahRcArea.SOUL_APPROACH);
		}
		else if (useBloodApproach(step, start, mode))
		{
			path = waypointApproachPath(worldView, start, end, ZeahRcArea.BLOOD_APPROACH);
		}
		else if (keepBloodAltarLoaded && useDarkApproach(step, start, mode))
		{
			path = waypointApproachPath(
				worldView,
				start,
				end,
				List.of(ZeahRcArea.DARK_APPROACH),
				transports(agility, step, start, mode, atMine));
		}
		else
		{
			path = Pathfinder.find(worldView, start, end, transports(agility, step, start, mode, atMine));
		}

		cachedPath = path;
		cachedEnd = end;
		cachedStep = step;
		cachedAgility = agility;
		return Pathfinder.simplify(path);
	}

	ClickTarget nextClick(RotationStep step, TileObject destination, List<WorldPoint> path, WorldPoint player, boolean atMine)
	{
		if (step == RotationStep.CHISEL_AT_ALTAR || step == RotationStep.IDLE)
		{
			return ClickTarget.none();
		}
		if (player == null)
		{
			return ClickTarget.of(destination, null);
		}
		if (destination == null && needsRunestone(step) && atMine)
		{
			return ClickTarget.none();
		}
		if (destination != null && SceneTracker.distanceTo(destination, player) <= AT_TARGET_TILES)
		{
			return ClickTarget.of(destination, null);
		}

		AgilityShortcut.Hop hop = AgilityShortcut.firstHop(path, player);
		if (hop != null)
		{
			TileObject shortcut = objectForHop(hop);
			if (shortcut != null)
			{
				return ClickTarget.of(shortcut, null);
			}
			return ClickTarget.of(null, hop.getFrom());
		}
		return ClickTarget.of(destination, null);
	}

	static boolean needsRunestone(RotationStep step)
	{
		return step == RotationStep.MINE_FIRST
			|| step == RotationStep.MINE_SECOND
			|| step == RotationStep.RETURN_TO_MINE
			|| step == RotationStep.CHISEL_AND_RETURN;
	}

	static List<Pathfinder.Transport> transports(
		int agility,
		RotationStep step,
		WorldPoint player,
		RcMode mode,
		boolean atMine)
	{
		List<Pathfinder.Transport> out = new ArrayList<>();
		for (AgilityShortcut shortcut : AgilityShortcut.values())
		{
			if (!shortcut.enabled(agility, step, player, mode, atMine))
			{
				continue;
			}
			out.add(new Pathfinder.Transport(shortcut.getFrom(), shortcut.getTo()));
			if (shortcut.isBidirectional())
			{
				out.add(new Pathfinder.Transport(shortcut.getTo(), shortcut.getFrom()));
			}
		}
		return out;
	}

	static boolean useSoulApproach(RotationStep step, WorldPoint start, RcMode mode, boolean atMine)
	{
		if (step != RotationStep.GO_ALTAR || mode != RcMode.SOUL || start == null || atMine)
		{
			return false;
		}
		return start.getY() >= 3875 && start.getX() <= 1796;
	}

	static boolean useBloodApproach(RotationStep step, WorldPoint start, RcMode mode)
	{
		if (step != RotationStep.GO_ALTAR || mode != RcMode.BLOOD || start == null)
		{
			return false;
		}
		if (start.distanceTo(ZeahRcArea.BLOOD_ALTAR) <= 12)
		{
			return false;
		}
		return start.getX() <= 1745;
	}

	/**
	 * Blood trips reach the Dark Altar via {@link ZeahRcArea#DARK_APPROACH} so the scene
	 * rebuild fires there and keeps the Blood Altar loaded for a long-range click. Off once the
	 * player is within four tiles of the approach tile, which includes standing at the Dark Altar.
	 */
	static boolean useDarkApproach(RotationStep step, WorldPoint start, RcMode mode)
	{
		if (step != RotationStep.GO_DARK_FIRST && step != RotationStep.GO_DARK_SECOND)
		{
			return false;
		}
		if (mode != RcMode.BLOOD || start == null)
		{
			return false;
		}
		return start.distanceTo(ZeahRcArea.DARK_APPROACH) > 4;
	}

	private TileObject objectForHop(AgilityShortcut.Hop hop)
	{
		int id = AgilityShortcut.objectIdForHop(hop.getFrom(), hop.getTo());
		return id < 0 ? null : sceneTracker.objectForShortcutId(id);
	}

	private List<WorldPoint> routeViaShortcut(
		WorldView worldView,
		WorldPoint start,
		WorldPoint end,
		AgilityShortcut shortcut)
	{
		List<WorldPoint> path = new ArrayList<>();
		WorldPoint origin = shortcut.getFrom();
		WorldPoint landing = shortcut.getTo();
		if (start.distanceTo(origin) <= AT_TARGET_TILES)
		{
			path.add(origin);
		}
		else
		{
			List<WorldPoint> toOrigin = Pathfinder.find(worldView, start, origin, Collections.emptyList());
			if (!toOrigin.isEmpty())
			{
				appendLeg(path, toOrigin);
			}
			else
			{
				path.add(start);
			}
			if (path.isEmpty() || !path.get(path.size() - 1).equals(origin))
			{
				path.add(origin);
			}
		}
		if (!path.get(path.size() - 1).equals(landing))
		{
			path.add(landing);
		}
		List<WorldPoint> onward = Pathfinder.find(worldView, landing, end, Collections.emptyList());
		if (!onward.isEmpty())
		{
			appendLeg(path, onward);
		}
		else if (end != null && !end.equals(landing))
		{
			path.add(end);
		}
		return path;
	}

	private List<WorldPoint> waypointApproachPath(
		WorldView worldView,
		WorldPoint start,
		WorldPoint end,
		List<WorldPoint> waypoints)
	{
		return waypointApproachPath(worldView, start, end, waypoints, Collections.emptyList());
	}

	private List<WorldPoint> waypointApproachPath(
		WorldView worldView,
		WorldPoint start,
		WorldPoint end,
		List<WorldPoint> waypoints,
		List<Pathfinder.Transport> transports)
	{
		int from = firstRemainingWaypoint(start, waypoints);
		List<WorldPoint> path = new ArrayList<>();
		WorldPoint cursor = start;
		for (int i = from; i < waypoints.size(); i++)
		{
			WorldPoint waypoint = waypoints.get(i);
			List<WorldPoint> leg = Pathfinder.find(worldView, cursor, waypoint, transports);
			if (!leg.isEmpty())
			{
				appendLeg(path, leg);
				cursor = waypoint;
				continue;
			}
			if (worldView == null || LocalPoint.fromWorld(worldView, waypoint) == null)
			{
				if (path.isEmpty() && !start.equals(waypoint))
				{
					path.add(start);
				}
				if (path.isEmpty() || !path.get(path.size() - 1).equals(waypoint))
				{
					path.add(waypoint);
				}
				cursor = waypoint;
			}
		}

		List<WorldPoint> finish = Pathfinder.find(worldView, cursor, end, transports);
		if (!finish.isEmpty())
		{
			appendLeg(path, finish);
		}
		else if (end != null && (worldView == null || LocalPoint.fromWorld(worldView, end) == null))
		{
			if (path.isEmpty())
			{
				path.add(start);
			}
			if (!path.get(path.size() - 1).equals(end))
			{
				path.add(end);
			}
		}
		return path;
	}

	static int firstRemainingWaypoint(WorldPoint start, List<WorldPoint> waypoints)
	{
		if (waypoints == null || waypoints.isEmpty())
		{
			return 0;
		}

		int last = waypoints.size() - 1;
		if (start.distanceTo(waypoints.get(last)) <= 4)
		{
			return waypoints.size();
		}

		int bestSeg = 0;
		int bestDist = start.distanceTo(waypoints.get(0));
		int bestT = 0;

		for (int i = 0; i < waypoints.size() - 1; i++)
		{
			int[] proj = projectOntoSegment(start, waypoints.get(i), waypoints.get(i + 1));
			if (proj[1] < bestDist)
			{
				bestDist = proj[1];
				bestSeg = i;
				bestT = proj[0];
			}
		}

		if (bestSeg == 0 && bestT == 0)
		{
			return 0;
		}
		if (bestT >= 1000 || start.distanceTo(waypoints.get(bestSeg + 1)) <= 4)
		{
			return Math.min(bestSeg + 2, waypoints.size());
		}
		return bestSeg + 1;
	}

	/**
	 * @return {t permille along A→B (0-1000), Chebyshev distance to the segment}
	 */
	static int[] projectOntoSegment(WorldPoint point, WorldPoint a, WorldPoint b)
	{
		int dx = b.getX() - a.getX();
		int dy = b.getY() - a.getY();
		int den = dx * dx + dy * dy;
		if (den == 0)
		{
			return new int[]{0, point.distanceTo(a)};
		}
		long t = (long) (point.getX() - a.getX()) * dx + (long) (point.getY() - a.getY()) * dy;
		if (t <= 0)
		{
			return new int[]{0, point.distanceTo(a)};
		}
		if (t >= den)
		{
			return new int[]{1000, point.distanceTo(b)};
		}
		int px = a.getX() + (int) (t * dx / den);
		int py = a.getY() + (int) (t * dy / den);
		int dist = Math.max(Math.abs(point.getX() - px), Math.abs(point.getY() - py));
		return new int[]{(int) (t * 1000 / den), dist};
	}

	static List<WorldPoint> trimPath(List<WorldPoint> path, WorldPoint start)
	{
		int best = 0;
		int bestDist = Integer.MAX_VALUE;
		for (int i = 0; i < path.size(); i++)
		{
			int dist = path.get(i).distanceTo(start);
			if (dist < bestDist)
			{
				bestDist = dist;
				best = i;
			}
		}
		if (bestDist > AgilityShortcut.PATH_DRIFT_TILES)
		{
			return null;
		}
		if (best == 0)
		{
			return path;
		}
		return new ArrayList<>(path.subList(best, path.size()));
	}

	private static void appendLeg(List<WorldPoint> path, List<WorldPoint> leg)
	{
		if (leg == null || leg.isEmpty())
		{
			return;
		}
		int start = 0;
		if (!path.isEmpty() && path.get(path.size() - 1).equals(leg.get(0)))
		{
			start = 1;
		}
		for (int i = start; i < leg.size(); i++)
		{
			path.add(leg.get(i));
		}
	}

	@Value
	static class ClickTarget
	{
		TileObject object;
		WorldPoint tile;

		static ClickTarget none()
		{
			return new ClickTarget(null, null);
		}

		static ClickTarget of(TileObject object, WorldPoint tile)
		{
			return new ClickTarget(object, tile);
		}
	}
}

package com.zeahrchelper;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

@Singleton
public class ReminderService
{
	private static final Pattern ESSENCE_CHARGES = Pattern.compile(
		"Your blood essence has (\\d{1,4}) charges? remaining",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern ESSENCE_EXTRACT = Pattern.compile(
		"You manage to extract power from the Blood Essence and craft (\\d{1,3}) extra runes?",
		Pattern.CASE_INSENSITIVE);
	private static final String ESSENCE_ACTIVATE = "You activate the blood essence.";
	private static final int MAX_BLOOD_ESSENCE_CHARGES = 1000;
	/** Matches RuneLite Item Charges plugin RS-profile key. */
	private static final String ITEM_CHARGE_GROUP = "itemCharge";
	private static final String ITEM_CHARGE_BLOOD_ESSENCE = "bloodEssence";

	private final Client client;
	private final ZeahRcHelperConfig config;
	private final ConfigManager configManager;

	@Getter
	private final List<String> warnings = new ArrayList<>();

	@Getter
	private Integer bloodEssenceCharges;

	@Getter
	private boolean idle;

	private Instant lastMoveAt = Instant.now();
	private WorldPoint lastTile;

	@Inject
	ReminderService(Client client, ZeahRcHelperConfig config, ConfigManager configManager)
	{
		this.client = client;
		this.config = config;
		this.configManager = configManager;
	}

	public void reset()
	{
		warnings.clear();
		bloodEssenceCharges = null;
		idle = false;
		lastMoveAt = Instant.now();
		lastTile = null;
	}

	public void onChatMessage(ChatMessage event)
	{
		if (event.getMessage() == null)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		Matcher check = ESSENCE_CHARGES.matcher(message);
		if (check.find())
		{
			setBloodEssenceCharges(Integer.parseInt(check.group(1)));
			return;
		}
		Matcher extract = ESSENCE_EXTRACT.matcher(message);
		if (extract.find())
		{
			int used = Integer.parseInt(extract.group(1));
			int current = bloodEssenceCharges != null
				? bloodEssenceCharges
				: readItemChargeCharges();
			if (current >= 0)
			{
				setBloodEssenceCharges(Math.max(0, current - used));
			}
			return;
		}
		if (message.contains(ESSENCE_ACTIVATE))
		{
			setBloodEssenceCharges(MAX_BLOOD_ESSENCE_CHARGES);
		}
	}

	public void update(InventorySnapshot inv, RcMode mode, boolean inArea)
	{
		warnings.clear();
		idle = false;

		if (!inArea || inv == null)
		{
			return;
		}

		updateIdle();
		syncBloodEssenceCharges(inv);

		if (inv.isHasFragments() && !inv.isFragmentsKnown())
		{
			warnings.add("Check your fragments - count unknown");
		}

		if (config.lanternReminder())
		{
			addGearWarnings(inv, mode);
		}

	}

	private void addGearWarnings(InventorySnapshot inv, RcMode mode)
	{
		if (!inv.isHasChisel())
		{
			warnings.add("Need a chisel");
		}
		if (!inv.isHasPickaxe())
		{
			warnings.add("Need a pickaxe");
		}
		addLanternWarnings(inv, mode);
	}

	private void addLanternWarnings(InventorySnapshot inv, RcMode mode)
	{
		if (!inv.isLanternEquipped())
		{
			if (inv.isLanternInInventory())
			{
				warnings.add("Equip your lantern");
			}
			else
			{
				warnings.add("Need a lantern");
			}
			return;
		}

		if (!config.lanternLogCheck())
		{
			return;
		}

		int id = inv.getLanternItemId();
		if (id == ItemID.ABYSSAL_LANTERN)
		{
			warnings.add("Light your lantern");
			return;
		}

		if (!isUsefulLantern(id, mode))
		{
			warnings.add("Wrong lantern logs");
		}
	}

	/**
	 * Logs that actually boost Zeah RC after the Aug 2026 lantern change:
	 * willow +5% runes, blisterwood +20% bloods, magic +10% runes, redwood = oak+willow.
	 */
	static boolean isUsefulLantern(int id, RcMode mode)
	{
		if (id == ItemID.ABYSSAL_LANTERN_MAGIC || id == ItemID.ABYSSAL_LANTERN_REDWOOD
			|| id == ItemID.ABYSSAL_LANTERN_WILLOW)
		{
			return true;
		}
		return mode == RcMode.BLOOD && id == ItemID.ABYSSAL_LANTERN_BLISTERWOOD;
	}

	private void syncBloodEssenceCharges(InventorySnapshot inv)
	{
		if (!inv.isHasActiveBloodEssence())
		{
			if (!inv.isHasInactiveBloodEssence())
			{
				bloodEssenceCharges = null;
			}
			return;
		}
		if (bloodEssenceCharges != null)
		{
			return;
		}
		int stored = readItemChargeCharges();
		if (stored >= 0)
		{
			bloodEssenceCharges = stored;
		}
	}

	private void setBloodEssenceCharges(int charges)
	{
		bloodEssenceCharges = Math.max(0, Math.min(MAX_BLOOD_ESSENCE_CHARGES, charges));
	}

	private int readItemChargeCharges()
	{
		try
		{
			Integer stored = configManager.getRSProfileConfiguration(
				ITEM_CHARGE_GROUP,
				ITEM_CHARGE_BLOOD_ESSENCE,
				Integer.class);
			return stored != null ? stored : -1;
		}
		catch (Exception ex)
		{
			return -1;
		}
	}

	private void updateIdle()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		// Standing still while mining or chiseling is not idle.
		if (isBusy())
		{
			lastTile = client.getLocalPlayer().getWorldLocation();
			lastMoveAt = Instant.now();
			idle = false;
			return;
		}

		WorldPoint now = client.getLocalPlayer().getWorldLocation();
		if (lastTile == null || now == null || lastTile.distanceTo(now) > 0)
		{
			lastTile = now;
			lastMoveAt = Instant.now();
			idle = false;
			return;
		}
		idle = Duration.between(lastMoveAt, Instant.now()).getSeconds() >= config.idleReminderSeconds();
	}

	private boolean isBusy()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		return player.getAnimation() != -1
			|| player.getPoseAnimation() != player.getIdlePoseAnimation();
	}
}

package com.zeahrchelper;

import java.awt.Color;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

@Slf4j
@Singleton
public class RotationHelper
{
	private static final int SOUL_LEVEL = 90;
	private static final int AT_ALTAR_TILES = 12;
	private static final int NEAR_ALTAR_TILES = 24;

	private final Client client;
	private final ZeahRcHelperConfig config;
	private final InventoryChecker inventoryChecker;
	private final ReminderService reminderService;
	private final SceneTracker sceneTracker;
	private final RcPathRouter pathRouter;
	private final ShortestPathBridge shortestPathBridge;

	@Getter
	private HelperAction currentAction = HelperAction.idle();

	@Getter
	private InventorySnapshot snapshot = new InventorySnapshot(
		0, 0, 0, 28, false, false, false, false, false, false, -1, true, false, 0, 0, false);

	@Getter
	private RcMode resolvedMode = RcMode.BLOOD;

	@Getter
	private final SessionStats sessionStats;

	private RotationStep lastStep = RotationStep.IDLE;
	/** True after the player clicks the Blood Altar during GO_ALTAR — hide Stand Here while walking. */
	private boolean bloodAltarClickCommitted;
	/** True once the Second Load has actually been mined this Trip - there is no Third Load. */
	private boolean secondLoadReached;

	@Inject
	RotationHelper(
		Client client,
		ZeahRcHelperConfig config,
		InventoryChecker inventoryChecker,
		ReminderService reminderService,
		SceneTracker sceneTracker,
		RcPathRouter pathRouter,
		ShortestPathBridge shortestPathBridge,
		SessionStats sessionStats)
	{
		this.client = client;
		this.config = config;
		this.inventoryChecker = inventoryChecker;
		this.reminderService = reminderService;
		this.sceneTracker = sceneTracker;
		this.pathRouter = pathRouter;
		this.shortestPathBridge = shortestPathBridge;
		this.sessionStats = sessionStats;
	}

	public void reset()
	{
		currentAction = HelperAction.idle();
		lastStep = RotationStep.IDLE;
		bloodAltarClickCommitted = false;
		secondLoadReached = false;
		sessionStats.clearBaselines();
		pathRouter.reset();
		shortestPathBridge.clear();
		inventoryChecker.reset();
	}

	public int getTripsCompleted()
	{
		return sessionStats.getTripsCompleted();
	}

	public int getBloodRunesCrafted()
	{
		return sessionStats.getBloodRunesCrafted();
	}

	public int getSoulRunesCrafted()
	{
		return sessionStats.getSoulRunesCrafted();
	}

	public int getTotalTrips()
	{
		return sessionStats.getTotalTrips();
	}

	public int getTotalBloodRunes()
	{
		return sessionStats.getTotalBloodRunes();
	}

	public int getTotalSoulRunes()
	{
		return sessionStats.getTotalSoulRunes();
	}

	/** Re-read lifetime totals after login when the RS profile is available. */
	public void reloadSessionTotals()
	{
		sessionStats.reloadTotalsFromProfile();
	}

	/** Zero session and lifetime trip/rune counters. */
	public void resetAllCounters()
	{
		sessionStats.resetAllCounters();
	}

	/**
	 * Inventory changed mid-tick (craft completes). Counts runes using fragment consumption
	 * so we do not wait for the next game tick.
	 */
	public void onInventoryChanged()
	{
		snapshot = inventoryChecker.scan();
		sessionStats.noteRuneInventory(
			snapshot.getBloodRunes(), snapshot.getSoulRunes(), snapshot.isHasFragments());
	}

	/** Player clicked the Blood Altar — drop the stand-tile hint for the rest of this GO_ALTAR step. */
	public void onBloodAltarClicked()
	{
		if (lastStep == RotationStep.GO_ALTAR && resolvedMode == RcMode.BLOOD)
		{
			bloodAltarClickCommitted = true;
		}
	}

	public void update()
	{
		if (!ZeahRcArea.isInArceuusRc(client))
		{
			currentAction = HelperAction.idle();
			bloodAltarClickCommitted = false;
			pathRouter.reset();
			shortestPathBridge.clear();
			snapshot = inventoryChecker.scan();
			sessionStats.noteRuneInventory(
				snapshot.getBloodRunes(), snapshot.getSoulRunes(), snapshot.isHasFragments());
			sessionStats.onGameTick();
			reminderService.update(snapshot, resolvedMode, false);
			return;
		}

		resolvedMode = resolveMode();
		snapshot = inventoryChecker.scan();
		reminderService.update(snapshot, resolvedMode, true);

		if (!config.enableHelper())
		{
			currentAction = HelperAction.idle();
			pathRouter.reset();
			shortestPathBridge.clear();
			sessionStats.noteRuneInventory(
				snapshot.getBloodRunes(), snapshot.getSoulRunes(), snapshot.isHasFragments());
			sessionStats.onGameTick();
			return;
		}

		boolean atAltar = sceneTracker.isNearAltar(resolvedMode, AT_ALTAR_TILES);
		boolean nearAltar = atAltar || sceneTracker.isNearAltar(resolvedMode, NEAR_ALTAR_TILES);
		Player player = client.getLocalPlayer();
		WorldPoint start = player == null ? null : player.getWorldLocation();
		boolean atMine = start != null && sceneTracker.isAtMine(start);

		RotationStep step = RotationLogic.infer(snapshot, atAltar, nearAltar, atMine, lastStep, secondLoadReached);
		if (RotationLogic.isTripCompleteTransition(lastStep, step))
		{
			sessionStats.noteTripComplete();
			secondLoadReached = false;
		}
		if (RotationLogic.marksSecondLoadReached(step))
		{
			secondLoadReached = true;
		}
		sessionStats.noteRuneInventory(
			snapshot.getBloodRunes(), snapshot.getSoulRunes(), snapshot.isHasFragments());
		sessionStats.onGameTick();
		if (step != RotationStep.GO_ALTAR)
		{
			bloodAltarClickCommitted = false;
		}
		lastStep = step;

		boolean bloodAltarInScene = sceneTracker.isBloodAltarInScene();
		BloodAltarReach.State altarReach = BloodAltarReach.evaluate(
			step,
			resolvedMode,
			start,
			bloodAltarInScene,
			bloodAltarClickCommitted);
		if (step == RotationStep.GO_ALTAR && resolvedMode == RcMode.BLOOD
			&& altarReach != BloodAltarReach.State.READY)
		{
			WorldView diagnosticView = client.getTopLevelWorldView();
			log.debug(
				"GO_ALTAR not ready: reach={} altarInScene={} bloodAltarSpawned={} reachTo={} tile={}"
					+ " sceneBase=({},{}) sceneSize=({},{})",
				altarReach, bloodAltarInScene, sceneTracker.getBloodAltar() != null,
				start == null ? -1 : BloodAltarReach.reachTo(start), start,
				diagnosticView == null ? -1 : diagnosticView.getBaseX(),
				diagnosticView == null ? -1 : diagnosticView.getBaseY(),
				diagnosticView == null ? -1 : diagnosticView.getSizeX(),
				diagnosticView == null ? -1 : diagnosticView.getSizeY());
		}

		TileObject destination = destinationObject(step, altarReach);
		WorldPoint end = pathEnd(destination, step, start, altarReach);
		WorldView worldView = client.getTopLevelWorldView();
		int agility = client.getRealSkillLevel(Skill.AGILITY);
		Color color = colorFor(step);
		boolean ownPath = !config.pathDisplay().isOff() && !shortestPathBridge.isDriving();
		List<WorldPoint> path = pathRouter.pathTo(
			worldView,
			start,
			end,
			step,
			agility,
			resolvedMode,
			atMine,
			ownPath,
			resolvedMode == RcMode.BLOOD);
		RcPathRouter.ClickTarget click = nextClick(step, destination, path, start, atMine, altarReach);
		shortestPathBridge.update(shortestPathTarget(end, step, altarReach), color);
		currentAction = new HelperAction(
			step,
			detailFor(step, altarReach),
			path,
			click.getObject(),
			click.getTile(),
			color,
			worldHintFor(altarReach));
	}

	private RcPathRouter.ClickTarget nextClick(
		RotationStep step,
		TileObject destination,
		List<WorldPoint> path,
		WorldPoint start,
		boolean atMine,
		BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return RcPathRouter.ClickTarget.of(null, ZeahRcArea.DARK_APPROACH);
		}
		return pathRouter.nextClick(step, destination, path, start, atMine);
	}

	/**
	 * Shortest Path targets must be walkable. Object SW tiles (runestones, altars) are often
	 * collision-blocked, which makes SP report "Destination could not be reached".
	 */
	private WorldPoint shortestPathTarget(WorldPoint end, RotationStep step, BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return ZeahRcArea.DARK_APPROACH;
		}
		if (end == null)
		{
			return null;
		}
		switch (step)
		{
			case MINE_FIRST:
			case MINE_SECOND:
			case CHISEL_AND_RETURN:
			case RETURN_TO_MINE:
				return ZeahRcArea.MINE_STAND;
			case GO_DARK_FIRST:
			case GO_DARK_SECOND:
				return ZeahRcArea.DARK_ALTAR;
			case GO_ALTAR:
			case CRAFT_FRAGMENTS:
			case CRAFT_REMAINING:
			case CHISEL_AT_ALTAR:
				return resolvedMode == RcMode.SOUL ? ZeahRcArea.SOUL_ALTAR : ZeahRcArea.BLOOD_ALTAR;
			default:
				return end;
		}
	}

	private TileObject destinationObject(RotationStep step, BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return null;
		}
		switch (step)
		{
			case MINE_FIRST:
			case MINE_SECOND:
				return sceneTracker.chooseRunestone();
			case GO_DARK_FIRST:
			case GO_DARK_SECOND:
				return sceneTracker.getDarkAltar();
			case GO_ALTAR:
			case CRAFT_FRAGMENTS:
			case CRAFT_REMAINING:
				return sceneTracker.altarFor(resolvedMode);
			case CHISEL_AT_ALTAR:
				return null;
			case CHISEL_AND_RETURN:
			case RETURN_TO_MINE:
				if (step == RotationStep.CHISEL_AND_RETURN)
				{
					Player p = client.getLocalPlayer();
					TileObject stone = sceneTracker.chooseRunestone();
					// Loose isAtMine includes the west-73 landing — only drop the target when
					// actually next to a runestone.
					if (p != null && stone != null
						&& SceneTracker.distanceTo(stone, p.getWorldLocation()) <= 1)
					{
						return null;
					}
				}
				return sceneTracker.chooseRunestone();
			default:
				return null;
		}
	}

	private WorldPoint pathEnd(
		TileObject destination,
		RotationStep step,
		WorldPoint start,
		BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return ZeahRcArea.DARK_APPROACH;
		}
		if (destination != null)
		{
			return destination.getWorldLocation();
		}
		// Only mining steps clear the path on loose isAtMine. Chisel/return must keep pathing
		// after the west-73 landing (inside the mine radius but still short of the stones).
		if (sceneTracker.isAtMine(start)
			&& (step == RotationStep.MINE_FIRST || step == RotationStep.MINE_SECOND))
		{
			return null;
		}
		return fallbackTile(step);
	}

	private WorldPoint fallbackTile(RotationStep step)
	{
		switch (step)
		{
			case MINE_FIRST:
			case MINE_SECOND:
			case CHISEL_AND_RETURN:
			case RETURN_TO_MINE:
				return ZeahRcArea.MINE_STAND;
			case GO_DARK_FIRST:
			case GO_DARK_SECOND:
				return ZeahRcArea.DARK_ALTAR;
			case GO_ALTAR:
			case CRAFT_FRAGMENTS:
			case CRAFT_REMAINING:
			case CHISEL_AT_ALTAR:
				return resolvedMode == RcMode.SOUL ? ZeahRcArea.SOUL_ALTAR : ZeahRcArea.BLOOD_ALTAR;
			default:
				return null;
		}
	}

	private Color colorFor(RotationStep step)
	{
		switch (step)
		{
			case GO_ALTAR:
			case CRAFT_FRAGMENTS:
			case CRAFT_REMAINING:
				return resolvedMode.getColor();
			default:
				return step.getColor();
		}
	}

	private RcMode resolveMode()
	{
		if (config.mode() != RcMode.AUTO)
		{
			return config.mode();
		}
		return client.getRealSkillLevel(Skill.RUNECRAFT) >= SOUL_LEVEL ? RcMode.SOUL : RcMode.BLOOD;
	}

	private static String worldHintFor(BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return "Stand Here";
		}
		if (altarReach == BloodAltarReach.State.READY)
		{
			return "Click Here";
		}
		return null;
	}

	private String detailFor(RotationStep step, BloodAltarReach.State altarReach)
	{
		if (altarReach == BloodAltarReach.State.STAND_THEN_CLICK)
		{
			return "Stand Here, then click the Blood Altar";
		}
		if (altarReach == BloodAltarReach.State.READY)
		{
			return "Click the Blood Altar";
		}
		String rune = resolvedMode == RcMode.SOUL ? "soul" : "blood";
		switch (step)
		{
			case MINE_FIRST:
				return "Fill your first inventory";
			case GO_DARK_FIRST:
				return "Click the Dark Altar to venerate all dense blocks";
			case CHISEL_AND_RETURN:
				return "Use chisel on dark blocks while running back to the mine";
			case MINE_SECOND:
				return "Fill your second inventory";
			case GO_DARK_SECOND:
				return "Venerate the second inventory at the Dark Altar";
			case GO_ALTAR:
				return "Carry fragments + dark blocks to the " + rune + " altar";
			case CRAFT_FRAGMENTS:
				return "Click the " + rune + " altar to craft your fragments";
			case CHISEL_AT_ALTAR:
				return "Chisel the remaining dark blocks into fragments";
			case CRAFT_REMAINING:
				return "Click the " + rune + " altar again for the second batch";
			case RETURN_TO_MINE:
				return "Take the shortcut back to the dense essence mine";
			default:
				return step.getLabel();
		}
	}
}

package com.zeahrchelper;

/**
 * Pure rotation step inference and trip counting, free of the RuneLite client so it can be
 * unit-tested. {@link RotationHelper} supplies the location flags each tick.
 */
final class RotationLogic
{
	/** Enough Fragments held that the next load of Dense Blocks goes straight to the altar. */
	static final int FULL_FRAGMENTS = 100;

	private RotationLogic()
	{
	}

	static RotationStep infer(
		InventorySnapshot inv,
		boolean atAltar,
		boolean nearAltar,
		boolean atMine,
		RotationStep lastStep)
	{
		return infer(inv, atAltar, nearAltar, atMine, lastStep, false);
	}

	/**
	 * @param secondLoadReached True once the Second Load has actually been mined this Trip -
	 * there is no Third Load, so finishing this Load's Dark Blocks with nothing left to mine
	 * means craft, not another mining pass.
	 */
	static RotationStep infer(
		InventorySnapshot inv,
		boolean atAltar,
		boolean nearAltar,
		boolean atMine,
		RotationStep lastStep,
		boolean secondLoadReached)
	{
		boolean hasFrags = inv.getFragments() > 0;
		boolean hasDark = inv.getDarkBlocks() > 0;
		boolean hasDense = inv.getDenseBlocks() > 0;
		boolean inventoryFull = inv.getEmptySlots() == 0;
		boolean fullFragmentStack = inv.isFragmentsKnown() && inv.getFragments() >= FULL_FRAGMENTS;
		// Mid first-load chisel looks like the second load once the stack hits Full with dark left.
		boolean chiselling = lastStep == RotationStep.CHISEL_AND_RETURN;
		// A fresh Check confirming Full is a deliberate signal, unlike Full inferred from this run's
		// own chiselling - let it break the keep-chiselling veto instead of waiting on nearAltar.
		// Only once the Second Load is reached, though: on the First Load, Full must not skip
		// mining the Second Load entirely - a Trip is always both Loads.
		boolean checkOverride = secondLoadReached && inv.isFragmentsCheckConfirmed() && fullFragmentStack;
		boolean chisellingVeto = chiselling && !checkOverride;
		// There is no Third Load: once the Second Load's Dense is gone, everything left in the
		// bag (Dark, Fragments, any mix) is headed to the altar regardless of Fragment count -
		// GO_ALTAR already carries Dark blocks to be chiselled en route/at CHISEL_AT_ALTAR
		// (GitHub issue #12 - a fixed Fragment-count threshold never fires when reduced inventory
		// space keeps the Load's chiselled total under it).
		boolean secondLoadFinishedMining = secondLoadReached && !hasDense;

		if (atAltar)
		{
			if (hasFrags)
			{
				return secondBatch(lastStep) ? RotationStep.CRAFT_REMAINING : RotationStep.CRAFT_FRAGMENTS;
			}
			if (hasDark)
			{
				return RotationStep.CHISEL_AT_ALTAR;
			}
			return RotationStep.RETURN_TO_MINE;
		}

		if (hasDark && secondLoadFinishedMining)
		{
			return RotationStep.GO_ALTAR;
		}
		if (hasFrags && hasDark && (nearAltar || (!chisellingVeto && fullFragmentStack)))
		{
			return RotationStep.GO_ALTAR;
		}
		if (hasDense && inventoryFull)
		{
			return fullFragmentStack || hasFrags ? RotationStep.GO_DARK_SECOND : RotationStep.GO_DARK_FIRST;
		}
		if (hasDark && (chisellingVeto || !fullFragmentStack))
		{
			return RotationStep.CHISEL_AND_RETURN;
		}
		if (hasFrags && !hasDark && !hasDense)
		{
			if (secondLoadReached)
			{
				// Both Loads are fully chiselled with nothing left to mine - go craft.
				return RotationStep.GO_ALTAR;
			}
			return atMine ? RotationStep.MINE_SECOND : RotationStep.RETURN_TO_MINE;
		}
		if (!atMine && hasDense && !fullFragmentStack)
		{
			return hasFrags ? RotationStep.GO_DARK_SECOND : RotationStep.GO_DARK_FIRST;
		}
		return hasFrags ? RotationStep.MINE_SECOND : RotationStep.MINE_FIRST;
	}

	/** The second batch follows chiselling at the altar; it stays until the player leaves. */
	static boolean secondBatch(RotationStep lastStep)
	{
		return lastStep == RotationStep.CHISEL_AT_ALTAR || lastStep == RotationStep.CRAFT_REMAINING;
	}

	static boolean isTripCompleteTransition(RotationStep from, RotationStep to)
	{
		return (from == RotationStep.CRAFT_REMAINING || from == RotationStep.RETURN_TO_MINE)
			&& to == RotationStep.MINE_FIRST;
	}

	/**
	 * True once inferring this step proves the Second Load has actually been mined, not merely
	 * prompted. MINE_SECOND is just the "go mine now" instruction shown while still empty-handed -
	 * treating it as reached would flip secondLoadReached before any mining happens, making the
	 * very next tick's identical empty-handed state (still no Dense/Dark, just Fragments) misread
	 * as the Second Load already being finished too (GitHub issue #9).
	 */
	static boolean marksSecondLoadReached(RotationStep step)
	{
		return step == RotationStep.GO_DARK_SECOND;
	}
}

package com.zeahrchelper;

import java.awt.Color;
import java.util.List;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * Click-here steps for the standard Arceuus blood/soul rotation.
 */
@Getter
public enum RotationStep
{
	MINE_FIRST("Mine", Color.CYAN),
	GO_DARK_FIRST("Venerate", new Color(160, 80, 255)),
	CHISEL_AND_RETURN("Chisel", Color.ORANGE),
	MINE_SECOND("Mine again", Color.CYAN),
	GO_DARK_SECOND("Venerate", new Color(160, 80, 255)),
	GO_ALTAR("Altar", new Color(220, 40, 40)),
	CRAFT_FRAGMENTS("Craft", new Color(220, 40, 40)),
	CHISEL_AT_ALTAR("Chisel", Color.ORANGE),
	CRAFT_REMAINING("Craft", new Color(220, 40, 40)),
	RETURN_TO_MINE("Return", Color.CYAN),
	IDLE("Waiting…", Color.GRAY);

	private final String label;
	private final Color color;

	RotationStep(String label, Color color)
	{
		this.label = label;
		this.color = color;
	}

	public List<WorldPoint> highlightTiles(RcMode resolvedMode)
	{
		switch (this)
		{
			case MINE_FIRST:
			case MINE_SECOND:
				return ZeahRcArea.RUNESTONES;
			case GO_DARK_FIRST:
			case GO_DARK_SECOND:
				return List.of(ZeahRcArea.DARK_ALTAR);
			case CHISEL_AND_RETURN:
				return List.of(ZeahRcArea.NORTH_SHORTCUT, ZeahRcArea.MINE_STAND);
			case RETURN_TO_MINE:
				return List.of(ZeahRcArea.BOULDER_SHORTCUT, ZeahRcArea.SHORTCUT, ZeahRcArea.NORTH_SHORTCUT, ZeahRcArea.MINE_STAND);
			case GO_ALTAR:
			case CRAFT_FRAGMENTS:
			case CRAFT_REMAINING:
				return List.of(resolvedMode == RcMode.SOUL ? ZeahRcArea.SOUL_ALTAR : ZeahRcArea.BLOOD_ALTAR);
			case CHISEL_AT_ALTAR:
				return List.of(resolvedMode == RcMode.SOUL ? ZeahRcArea.SOUL_ALTAR : ZeahRcArea.BLOOD_ALTAR);
			default:
				return List.of();
		}
	}
}

package com.zeahrchelper;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/**
 * Tracks Arceuus RC scene objects from spawn/despawn (and a one-shot scan on login).
 */
@Singleton
public class SceneTracker
{
	private static final int RUNESTONE_NEAR_TILES = 4;

	private final Client client;

	@Getter
	private TileObject runestoneNorth;
	@Getter
	private TileObject runestoneSouth;
	@Getter
	private TileObject darkAltar;
	@Getter
	private TileObject bloodAltar;
	@Getter
	private TileObject soulAltar;
	@Getter
	private TileObject shortcut73;
	@Getter
	private TileObject shortcut69;
	@Getter
	private TileObject shortcut52Outer;
	@Getter
	private TileObject shortcut52Inner;
	@Getter
	private TileObject shortcut49;

	@Inject
	SceneTracker(Client client)
	{
		this.client = client;
	}

	public void reset()
	{
		runestoneNorth = null;
		runestoneSouth = null;
		darkAltar = null;
		bloodAltar = null;
		soulAltar = null;
		shortcut73 = null;
		shortcut69 = null;
		shortcut52Outer = null;
		shortcut52Inner = null;
		shortcut49 = null;
	}

	public void onSpawn(TileObject object)
	{
		try
		{
			if (object == null)
			{
				return;
			}
			assign(object, false);
		}
		catch (Exception ex)
		{
			// Simulated scene events during startup should never break the plugin.
		}
	}

	public void onDespawn(TileObject object)
	{
		try
		{
			if (object == null)
			{
				return;
			}
			assign(object, true);
		}
		catch (Exception ex)
		{
			// ignore
		}
	}

	public void scanScene()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		Scene scene = worldView.getScene();
		if (scene == null)
		{
			return;
		}

		Tile[][][] tiles = scene.getTiles();
		if (tiles == null)
		{
			return;
		}

		int z = worldView.getPlane();
		if (z < 0 || z >= tiles.length || tiles[z] == null)
		{
			return;
		}

		for (Tile[] row : tiles[z])
		{
			if (row == null)
			{
				continue;
			}
			for (Tile tile : row)
			{
				scanTile(tile);
			}
		}
	}

	public boolean isNorthMineable()
	{
		return mineableFromVarbits(true);
	}

	public boolean isSouthMineable()
	{
		return mineableFromVarbits(false);
	}

	public TileObject chooseRunestone()
	{
		Player player = client.getLocalPlayer();
		if (isMining(player))
		{
			return null;
		}

		WorldPoint loc = player == null ? null : player.getWorldLocation();
		boolean northDense = isNorthMineable();
		boolean southDense = isSouthMineable();

		if (northDense && southDense)
		{
			boolean atNorth = loc != null && distanceTo(runestoneNorth, loc) <= RUNESTONE_NEAR_TILES;
			return atNorth ? runestoneNorth : runestoneSouth;
		}
		if (southDense)
		{
			return runestoneSouth;
		}
		if (northDense)
		{
			return runestoneNorth;
		}
		return null;
	}

	private static boolean isMining(Player player)
	{
		if (player == null)
		{
			return false;
		}
		return player.getAnimation() != -1;
	}

	public TileObject altarFor(RcMode mode)
	{
		return mode == RcMode.SOUL ? soulAltar : bloodAltar;
	}

	public boolean isNearAltar(RcMode mode, int tiles)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint loc = player.getWorldLocation();
		if (distanceTo(altarFor(mode), loc) <= tiles)
		{
			return true;
		}
		WorldPoint fallback = mode == RcMode.SOUL ? ZeahRcArea.SOUL_ALTAR : ZeahRcArea.BLOOD_ALTAR;
		return loc.distanceTo(fallback) <= tiles;
	}

	/**
	 * True once the Blood Altar GameObject has actually spawned, or its tile lies inside the base
	 * 104x104 scene (not the extended band) as a fallback for before its spawn event has fired.
	 */
	public boolean isBloodAltarInScene()
	{
		if (bloodAltar != null)
		{
			return true;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return false;
		}
		WorldPoint p = ZeahRcArea.BLOOD_ALTAR;
		return WorldPoint.isInScene(wv, p.getX(), p.getY());
	}

	public TileObject objectForShortcutId(int id)
	{
		if (id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_BOULDER)
		{
			return shortcut49;
		}
		if (id == AgilityShortcut.NORTH_OBJECT_ID)
		{
			return shortcut69;
		}
		if (id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_BOTTOM)
		{
			return shortcut52Inner;
		}
		if (id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_TOP)
		{
			return shortcut52Outer;
		}
		if (id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_TOP
			|| id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_BOTTOM
			|| id == ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_MIDDLE)
		{
			return shortcut73;
		}
		return null;
	}

	public boolean isAtMine(WorldPoint loc)
	{
		if (loc == null)
		{
			return false;
		}
		if (distanceTo(runestoneNorth, loc) <= 8 || distanceTo(runestoneSouth, loc) <= 8)
		{
			return true;
		}
		return loc.distanceTo(ZeahRcArea.RUNESTONE_SOUTH) <= 10
			|| loc.distanceTo(ZeahRcArea.RUNESTONE_NORTH) <= 10;
	}

	static int distanceTo(TileObject object, WorldPoint loc)
	{
		if (object == null || loc == null)
		{
			return Integer.MAX_VALUE;
		}
		if (object instanceof GameObject)
		{
			GameObject go = (GameObject) object;
			WorldArea area = new WorldArea(go.getWorldLocation(), Math.max(1, go.sizeX()), Math.max(1, go.sizeY()));
			return area.distanceTo(loc);
		}
		return object.getWorldLocation().distanceTo(loc);
	}

	private void scanTile(Tile tile)
	{
		if (tile == null)
		{
			return;
		}
		GameObject[] objects = tile.getGameObjects();
		if (objects != null)
		{
			for (GameObject object : objects)
			{
				onSpawn(object);
			}
		}
		DecorativeObject deco = tile.getDecorativeObject();
		if (deco != null)
		{
			onSpawn(deco);
		}
		GroundObject ground = tile.getGroundObject();
		if (ground != null)
		{
			onSpawn(ground);
		}
		WallObject wall = tile.getWallObject();
		if (wall != null)
		{
			onSpawn(wall);
		}
	}

	private void assign(TileObject object, boolean despawn)
	{
		int id = object.getId();
		switch (id)
		{
			// The base objects persist through depletion; the varbits carry the mineable state.
			case ObjectID.ARCEUUS_RUNESTONE_BASE_1:
				runestoneNorth = despawn ? clear(runestoneNorth, object) : object;
				break;
			case ObjectID.ARCEUUS_RUNESTONE_BASE_2:
				runestoneSouth = despawn ? clear(runestoneSouth, object) : object;
				break;
			case ObjectID.ARCEUUS_ALTAR:
			case ObjectID.ARCHEUS_ALTAR_DARK:
				darkAltar = despawn ? clear(darkAltar, object) : prefer(darkAltar, object);
				break;
			case ObjectID.ARCHEUS_ALTAR_BLOOD:
				bloodAltar = despawn ? clear(bloodAltar, object) : prefer(bloodAltar, object);
				break;
			case ObjectID.ARCHEUS_ALTAR_SOUL:
				soulAltar = despawn ? clear(soulAltar, object) : prefer(soulAltar, object);
				break;
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_TOP:
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_BOTTOM:
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_MIDDLE:
				shortcut73 = despawn ? clear(shortcut73, object) : preferNear(shortcut73, object, ZeahRcArea.SHORTCUT);
				break;
			case AgilityShortcut.NORTH_OBJECT_ID:
				shortcut69 = despawn ? clear(shortcut69, object) : preferNear(shortcut69, object, ZeahRcArea.NORTH_SHORTCUT);
				break;
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_TOP:
				shortcut52Outer = despawn ? clear(shortcut52Outer, object) : preferNear(shortcut52Outer, object, ZeahRcArea.EAST_SHORTCUT);
				break;
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_BOTTOM:
				shortcut52Inner = despawn ? clear(shortcut52Inner, object) : preferNear(shortcut52Inner, object, ZeahRcArea.EAST_SHORTCUT);
				break;
			case ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_BOULDER:
				shortcut49 = despawn ? clear(shortcut49, object) : preferNear(shortcut49, object, ZeahRcArea.BOULDER_SHORTCUT);
				break;
			default:
				break;
		}
	}

	private static TileObject prefer(TileObject current, TileObject candidate)
	{
		return current == null ? candidate : current;
	}

	private static TileObject preferNear(TileObject current, TileObject candidate, WorldPoint expected)
	{
		if (current == null)
		{
			return candidate;
		}
		int currentDist = distanceToPoint(current, expected);
		int candidateDist = distanceToPoint(candidate, expected);
		return candidateDist < currentDist ? candidate : current;
	}

	private static int distanceToPoint(TileObject object, WorldPoint expected)
	{
		if (object == null || expected == null)
		{
			return Integer.MAX_VALUE;
		}
		WorldPoint loc = object.getWorldLocation();
		return loc == null ? Integer.MAX_VALUE : loc.distanceTo(expected);
	}

	private boolean mineableFromVarbits(boolean north)
	{
		int value = client.getVarbitValue(north ? VarbitID.ARCEUUS_RUNESTONE_1 : VarbitID.ARCEUUS_RUNESTONE_2);
		return value == 0;
	}

	private static TileObject clear(TileObject current, TileObject gone)
	{
		if (current == null || gone == null)
		{
			return current;
		}
		if (current == gone)
		{
			return null;
		}
		WorldPoint a = templatePointSafe(current);
		WorldPoint b = templatePointSafe(gone);
		if (current.getId() == gone.getId() && a != null && a.equals(b))
		{
			return null;
		}
		return current;
	}

	private static WorldPoint templatePointSafe(TileObject object)
	{
		try
		{
			return object.getWorldLocation();
		}
		catch (Exception ex)
		{
			return null;
		}
	}
}

package com.zeahrchelper;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;

/**
 * Session counters last for the client process (survive logout). Lifetime totals are stored on the
 * RuneLite RS profile and survive client restarts.
 * <p>
 * Crafted runes are credited only when the fragment stack leaves the inventory and blood/soul
 * quantity rises. Drop/pickup of runes alone does not remove fragments, so it is ignored.
 * Blood/soul quantity here already includes any held Rune Pouch/Divine Rune Pouch contents, so
 * runes the game deposits straight into a pouch instead of the inventory are still credited.
 */
@Singleton
public class SessionStats
{
	static final String KEY_TOTAL_TRIPS = "lifetimeTrips";
	static final String KEY_TOTAL_BLOOD = "lifetimeBloodRunes";
	static final String KEY_TOTAL_SOUL = "lifetimeSoulRunes";
	/** Ticks to wait for rune qty after fragments leave (split inventory updates). */
	private static final int PENDING_TICKS = 5;

	@Nullable
	private final ConfigManager configManager;

	@Getter
	private int tripsCompleted;
	@Getter
	private int bloodRunesCrafted;
	@Getter
	private int soulRunesCrafted;

	@Getter
	private int totalTrips;
	@Getter
	private int totalBloodRunes;
	@Getter
	private int totalSoulRunes;

	@Getter
	private int lastBloodQty = -1;
	@Getter
	private int lastSoulQty = -1;
	@Getter
	private boolean lastHadFragments;

	/** Fragments just left; waiting for the matching rune stack to rise. */
	private boolean waitingForRuneGain;
	private int waitBloodBaseline = -1;
	private int waitSoulBaseline = -1;
	private int pendingTicksRemaining;

	@Inject
	SessionStats(ConfigManager configManager)
	{
		this.configManager = configManager;
		reloadTotalsFromProfile();
	}

	SessionStats()
	{
		this.configManager = null;
	}

	public void reloadTotalsFromProfile()
	{
		totalTrips = readTotal(KEY_TOTAL_TRIPS);
		totalBloodRunes = readTotal(KEY_TOTAL_BLOOD);
		totalSoulRunes = readTotal(KEY_TOTAL_SOUL);
	}

	public void resetAllCounters()
	{
		tripsCompleted = 0;
		bloodRunesCrafted = 0;
		soulRunesCrafted = 0;
		totalTrips = 0;
		totalBloodRunes = 0;
		totalSoulRunes = 0;
		writeTotal(KEY_TOTAL_TRIPS, 0);
		writeTotal(KEY_TOTAL_BLOOD, 0);
		writeTotal(KEY_TOTAL_SOUL, 0);
		clearPending();
	}

	public void noteTripComplete()
	{
		tripsCompleted++;
		totalTrips++;
		writeTotal(KEY_TOTAL_TRIPS, totalTrips);
	}

	/**
	 * @param hasFragments whether a dark essence fragment stack is currently in the inventory
	 */
	public void noteRuneInventory(int bloodQty, int soulQty, boolean hasFragments)
	{
		bloodQty = Math.max(0, bloodQty);
		soulQty = Math.max(0, soulQty);

		if (lastBloodQty >= 0 && lastSoulQty >= 0 && lastHadFragments && !hasFragments)
		{
			int bloodDelta = bloodQty - lastBloodQty;
			int soulDelta = soulQty - lastSoulQty;
			if (bloodDelta > 0)
			{
				addBlood(bloodDelta);
				clearPending();
			}
			else if (soulDelta > 0)
			{
				addSoul(soulDelta);
				clearPending();
			}
			else
			{
				waitingForRuneGain = true;
				waitBloodBaseline = lastBloodQty;
				waitSoulBaseline = lastSoulQty;
				pendingTicksRemaining = PENDING_TICKS;
			}
		}
		else if (waitingForRuneGain)
		{
			if (waitBloodBaseline >= 0 && bloodQty > waitBloodBaseline)
			{
				addBlood(bloodQty - waitBloodBaseline);
				clearPending();
			}
			else if (waitSoulBaseline >= 0 && soulQty > waitSoulBaseline)
			{
				addSoul(soulQty - waitSoulBaseline);
				clearPending();
			}
		}

		lastBloodQty = bloodQty;
		lastSoulQty = soulQty;
		lastHadFragments = hasFragments;
	}

	/** Call after inventory has been processed for this tick. */
	public void onGameTick()
	{
		if (!waitingForRuneGain || pendingTicksRemaining <= 0)
		{
			return;
		}
		pendingTicksRemaining--;
		if (pendingTicksRemaining <= 0)
		{
			clearPending();
		}
	}

	public void clearBaselines()
	{
		lastBloodQty = -1;
		lastSoulQty = -1;
		lastHadFragments = false;
		clearPending();
	}

	private void addBlood(int delta)
	{
		bloodRunesCrafted += delta;
		totalBloodRunes += delta;
		writeTotal(KEY_TOTAL_BLOOD, totalBloodRunes);
	}

	private void addSoul(int delta)
	{
		soulRunesCrafted += delta;
		totalSoulRunes += delta;
		writeTotal(KEY_TOTAL_SOUL, totalSoulRunes);
	}

	private void clearPending()
	{
		waitingForRuneGain = false;
		waitBloodBaseline = -1;
		waitSoulBaseline = -1;
		pendingTicksRemaining = 0;
	}

	private int readTotal(String key)
	{
		if (configManager == null)
		{
			return 0;
		}
		try
		{
			Integer stored = configManager.getRSProfileConfiguration(
				ZeahRcHelperConfig.GROUP, key, Integer.class);
			return stored == null ? 0 : Math.max(0, stored);
		}
		catch (Exception ex)
		{
			return 0;
		}
	}

	private void writeTotal(String key, int value)
	{
		if (configManager == null)
		{
			return;
		}
		try
		{
			configManager.setRSProfileConfiguration(ZeahRcHelperConfig.GROUP, key, value);
		}
		catch (Exception ignored)
		{
		}
	}
}

package com.zeahrchelper;

import java.awt.Color;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * Hands the next destination to the Shortest Path plugin over the event bus, tinted with the
 * current step's colour. Shortest Path cannot be a compile-time dependency of a hub plugin, so the
 * whole integration is fire-and-forget {@link PluginMessage}.
 */
@Slf4j
@Singleton
class ShortestPathBridge
{
	private static final String NAMESPACE = "shortestpath";
	private static final String MESSAGE_PATH = "path";
	private static final String MESSAGE_CLEAR = "clear";
	private static final String MESSAGE_START = "start";
	private static final String MESSAGE_TARGET = "target";
	private static final String MESSAGE_CONFIG = "config";
	private static final String PLUGIN_NAME = "Shortest Path";

	/**
	 * Shortest Path keeps the full route from the posted start, so without a refresh the line
	 * behind you stays drawn and can look like a U-turn. Re-posting from the player every few
	 * ticks trims it the same way Jam's Solo Tempoross does. Walkable stand tiles (and matching
	 * calculating colour) keep that refresh from flashing purple unreachable.
	 */
	private static final int REFRESH_TICKS = 5;

	private final Client client;
	private final ZeahRcHelperConfig config;
	private final EventBus eventBus;
	private final PluginManager pluginManager;

	private WorldPoint postedTarget;
	private Color postedColor;
	private PathDisplay postedDisplay;
	private int postedTick;

	@Inject
	ShortestPathBridge(
		Client client,
		ZeahRcHelperConfig config,
		EventBus eventBus,
		PluginManager pluginManager)
	{
		this.client = client;
		this.config = config;
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
	}

	/** True when Shortest Path is picked and actually running, so it owns the path drawing. */
	boolean isDriving()
	{
		return config.pathProvider() == PathProvider.SHORTEST_PATH && isShortestPathRunning();
	}

	void update(WorldPoint destination, Color color)
	{
		PathDisplay display = config.pathDisplay();
		if (!isDriving() || display.isOff() || destination == null)
		{
			clear();
			return;
		}

		Player player = client.getLocalPlayer();
		WorldPoint start = player == null ? null : player.getWorldLocation();
		if (start == null)
		{
			clear();
			return;
		}

		int tick = client.getTickCount();
		boolean sameTarget = destination.equals(postedTarget);
		boolean unchanged = sameTarget && display == postedDisplay && Objects.equals(color, postedColor);
		if (unchanged && tick - postedTick < REFRESH_TICKS)
		{
			return;
		}

		if (!sameTarget)
		{
			log.debug("shortest path target {} -> {} (from {})", postedTarget, destination, start);
		}

		postedTarget = destination;
		postedColor = color;
		postedDisplay = display;
		postedTick = tick;

		Map<String, Object> data = new HashMap<>();
		data.put(MESSAGE_START, start);
		data.put(MESSAGE_TARGET, destination);
		data.put(MESSAGE_CONFIG, overrides(display, color));
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_PATH, data));
	}

	/** Drops our path and hands Shortest Path's own colours back to the user. */
	void clear()
	{
		if (postedTarget == null)
		{
			return;
		}
		postedTarget = null;
		postedColor = null;
		postedDisplay = null;
		postedTick = 0;
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_CLEAR));
	}

	/**
	 * Keys match Shortest Path's own config keys. Every path message replaces the whole override
	 * map, so this has to be complete each time.
	 */
	private static Map<String, Object> overrides(PathDisplay display, Color color)
	{
		Map<String, Object> overrides = new HashMap<>();
		overrides.put("colourPath", color);
		overrides.put("colourPathCalculating", color);
		overrides.put("colourPathUnreachable", color);
		overrides.put("pathStyle", "Lines");
		overrides.put("showTileCounter", "Disabled");
		overrides.put("drawTiles", display.showsFloor());
		overrides.put("drawMinimap", display.showsMinimap());
		overrides.put("drawMap", false);
		overrides.put("drawTransports", false);
		overrides.put("showTransportInfo", false);
		// Dense runestones / altar objects sit on blocked tiles; allow a short miss without the
		// purple unreachable flash. Prefer walkable stand tiles from RotationHelper when possible.
		overrides.put("unreachableTargetDistanceThreshold", 8);
		overrides.put("useAgilityShortcuts", true);
		overrides.put("useTeleportationItems", "None");
		overrides.put("useTeleportationSpells", false);
		overrides.put("useTeleportationSpellsHome", false);
		return overrides;
	}

	private boolean isShortestPathRunning()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}
}

package com.zeahrchelper;

import net.runelite.client.util.QuantityFormatter;

/**
 * Which counters the status panel Stats section shows: this client session, all-time total, or both.
 */
public enum StatsScope
{
	SESSION("Session"),
	TOTAL("Total"),
	SESSION_AND_TOTAL("Session/Total");

	private final String label;

	StatsScope(String label)
	{
		this.label = label;
	}

	/** Text inside {@code Stats (...)} on the panel. */
	public String panelSuffix()
	{
		return label;
	}

	public String format(int session, int total)
	{
		switch (this)
		{
			case SESSION:
				return formatCount(session);
			case TOTAL:
				return formatCount(total);
			case SESSION_AND_TOTAL:
			default:
				return formatCount(session) + "/" + formatCount(total);
		}
	}

	static String formatCount(int count)
	{
		return QuantityFormatter.quantityToStackSize((long) Math.max(0, count));
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.zeahrchelper;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

/**
 * Arceuus blood/soul runecrafting locations. Tiles are standing/click tiles for highlights;
 * they can be refined in-game if a highlight is a square off.
 */
public final class ZeahRcArea
{
	/** Dense essence mine, south runestone. */
	public static final WorldPoint RUNESTONE_SOUTH = new WorldPoint(1761, 3853, 0);
	/** Dense essence mine, north runestone. */
	public static final WorldPoint RUNESTONE_NORTH = new WorldPoint(1761, 3873, 0);
	public static final List<WorldPoint> RUNESTONES = List.of(RUNESTONE_SOUTH, RUNESTONE_NORTH);
	public static final WorldPoint MINE_STAND = new WorldPoint(1762, 3854, 0);
	public static final WorldPoint DARK_ALTAR = new WorldPoint(1718, 3882, 0);
	public static final WorldPoint BLOOD_ALTAR = new WorldPoint(1717, 3829, 0);
	/** South-west tile of the Blood Altar object's 4x4 footprint, read from the scene in game. */
	public static final WorldPoint BLOOD_ALTAR_FOOTPRINT_SW = new WorldPoint(1716, 3829, 0);
	public static final int BLOOD_ALTAR_FOOTPRINT_SIZE = 4;
	/**
	 * Where to reach before touching the Dark Altar on a blood trip: four tiles south of it. The
	 * scene rebuild then fires here and keeps the Blood Altar loaded. Also the nearest tile to the
	 * Dark Altar from which the Blood Altar can still be clicked.
	 */
	public static final WorldPoint DARK_APPROACH = new WorldPoint(1718, 3878, 0);
	public static final WorldPoint SOUL_ALTAR = new WorldPoint(1815, 3854, 0);
	/** 73 Agility rock scramble (west, blood altar → mine, one-way). */
	public static final WorldPoint SHORTCUT = new WorldPoint(1743, 3854, 0);
	/** 69 Agility northern scramble (mine ↔ Dark Altar). */
	public static final WorldPoint NORTH_SHORTCUT = new WorldPoint(1760, 3873, 0);
	/** 52 Agility eastern scramble. */
	public static final WorldPoint EAST_SHORTCUT = new WorldPoint(1771, 3851, 0);
	/** 49 Agility boulder (soul approach → mine, one-way). */
	public static final WorldPoint BOULDER_SHORTCUT = new WorldPoint(1775, 3888, 0);
	/**
	 * North-east crystal path from the Dark Altar toward the Soul Altar.
	 * Last tile is where the altar typically comes into the loaded scene.
	 */
	public static final List<WorldPoint> SOUL_APPROACH = List.of(
		new WorldPoint(1725, 3890, 0),
		new WorldPoint(1741, 3891, 0),
		new WorldPoint(1758, 3897, 0),
		new WorldPoint(1786, 3895, 0),
		new WorldPoint(1796, 3892, 0)
	);
	/**
	 * Dark Altar → Blood Altar walking path (west around the ridge, then south-east to the altar).
	 * Captured in-game from venerate to altar click.
	 */
	public static final List<WorldPoint> BLOOD_APPROACH = List.of(
		new WorldPoint(1701, 3880, 0),
		new WorldPoint(1674, 3879, 0),
		new WorldPoint(1659, 3881, 0),
		new WorldPoint(1661, 3863, 0),
		new WorldPoint(1675, 3859, 0),
		new WorldPoint(1731, 3856, 0),
		new WorldPoint(1735, 3849, 0),
		new WorldPoint(1735, 3828, 0),
		new WorldPoint(1728, 3826, 0),
		new WorldPoint(1717, 3826, 0)
	);

	/** Inclusive bounds for the Arceuus RC loop, including the west blood-altar walk. */
	private static final int AREA_MIN_X = 1650;
	private static final int AREA_MAX_X = 1836;
	private static final int AREA_MIN_Y = 3810;
	private static final int AREA_MAX_Y = 3908;

	private ZeahRcArea()
	{
	}

	public static boolean isInArceuusRc(Client client)
	{
		WorldPoint loc = player(client);
		if (loc == null)
		{
			return false;
		}
		return loc.getX() >= AREA_MIN_X && loc.getX() <= AREA_MAX_X
			&& loc.getY() >= AREA_MIN_Y && loc.getY() <= AREA_MAX_Y;
	}

	public static boolean isAtMine(Client client)
	{
		WorldPoint loc = player(client);
		return loc != null && (loc.distanceTo(RUNESTONE_SOUTH) <= 10 || loc.distanceTo(RUNESTONE_NORTH) <= 10);
	}

	public static boolean isAtDarkAltar(Client client)
	{
		WorldPoint loc = player(client);
		return loc != null && loc.distanceTo(DARK_ALTAR) <= 12;
	}

	public static boolean isAtBloodAltar(Client client)
	{
		WorldPoint loc = player(client);
		return loc != null && loc.distanceTo(BLOOD_ALTAR) <= 12;
	}

	public static boolean isAtSoulAltar(Client client)
	{
		WorldPoint loc = player(client);
		return loc != null && loc.distanceTo(SOUL_ALTAR) <= 12;
	}

	public static boolean isAtCraftAltar(Client client, RcMode mode)
	{
		return mode == RcMode.SOUL ? isAtSoulAltar(client) : isAtBloodAltar(client);
	}

	private static WorldPoint player(Client client)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}
		return client.getLocalPlayer().getWorldLocation();
	}
}

