		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
		this.client = client;
		this.config = config;
		this.rotationHelper = rotationHelper;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHelper() || !config.pathDisplay().showsMinimap())
		{
			return null;
		}

		HelperAction action = rotationHelper.getCurrentAction();
		if (action == null || action.getPath() == null || action.getPath().size() < 2)
		{
			return null;
		}

		Color base = action.getColor() != null ? action.getColor() : Color.CYAN;
		renderPath(graphics, action.getPath(), base);
		return null;
	}

	private void renderPath(Graphics2D graphics, List<WorldPoint> path, Color base)
	{
		Player player = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		Path2D.Float line = new Path2D.Float();
		boolean started = false;
		WorldPoint prevTile = player == null ? null : player.getWorldLocation();
		if (player != null)
		{
			Point mini = toMinimap(player.getWorldLocation(), worldView, player);
			if (mini != null)
			{
				line.moveTo(mini.getX(), mini.getY());
				started = true;
			}
		}

		for (int i = 0; i < path.size(); i++)
		{
			WorldPoint tile = path.get(i);
			Point mini = toMinimap(tile, worldView, player);
			if (mini == null)
			{
				prevTile = tile;
				continue;
			}
			boolean gap = AgilityShortcut.hopBetween(prevTile, tile);
			if (!started)
			{
				line.moveTo(mini.getX(), mini.getY());
				started = true;
			}
			else if (gap)
			{
				line.moveTo(mini.getX(), mini.getY());
			}
			else
			{
				line.lineTo(mini.getX(), mini.getY());
			}
			prevTile = tile;
		}

		if (!started)
		{
			return;
		}

		Stroke oldStroke = graphics.getStroke();
		Object oldHint = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setStroke(PATH_OUTLINE);
		graphics.setColor(new Color(0, 0, 0, 140));
		graphics.draw(line);
		graphics.setStroke(PATH_LINE);
		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), 220));
		graphics.draw(line);
		graphics.setStroke(oldStroke);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			oldHint != null ? oldHint : RenderingHints.VALUE_ANTIALIAS_OFF);
	}

	private Point toMinimap(WorldPoint tile, WorldView worldView, Player player)
	{
		if (tile == null)
		{
			return null;
		}
		LocalPoint local = LocalPoint.fromWorld(worldView, tile);
		if (local == null && player != null && player.getWorldLocation() != null)
		{
			LocalPoint here = player.getLocalLocation();
			WorldPoint playerWorld = player.getWorldLocation();
			if (here != null && playerWorld.getPlane() == tile.getPlane())
			{
				int x = here.getX() + (tile.getX() - playerWorld.getX()) * Perspective.LOCAL_TILE_SIZE;
				int y = here.getY() + (tile.getY() - playerWorld.getY()) * Perspective.LOCAL_TILE_SIZE;
				local = new LocalPoint(x, y, worldView);
			}
		}
		if (local == null)
		{
			return null;
		}
		return Perspective.localToMinimap(client, local, MINIMAP_RANGE);
	}
}

package com.zeahrchelper.overlay;

import com.zeahrchelper.HelperAction;
import com.zeahrchelper.InventorySnapshot;
import com.zeahrchelper.RcMode;
import com.zeahrchelper.ReminderService;
import com.zeahrchelper.RotationHelper;
import com.zeahrchelper.RotationStep;
import com.zeahrchelper.StatsScope;
import com.zeahrchelper.ZeahRcHelperConfig;
import com.zeahrchelper.ZeahRcHelperPlugin;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

public class StatusOverlay extends OverlayPanel
{
	private static final Color LABEL = Color.WHITE;
	private static final Color DETAIL = new Color(170, 170, 170);
	private static final Color WARN = new Color(255, 168, 76);
	private static final Color ESSENCE_OK = new Color(120, 200, 140);
	private static final Dimension SIZE = new Dimension(200, 0);

	private final ZeahRcHelperConfig config;
	private final RotationHelper rotationHelper;
	private final ReminderService reminderService;

	@Inject
	private StatusOverlay(
		ZeahRcHelperPlugin plugin,
		ZeahRcHelperConfig config,
		RotationHelper rotationHelper,
		ReminderService reminderService)
	{
		super(plugin);
		setPosition(OverlayPosition.TOP_LEFT);
		this.config = config;
		this.rotationHelper = rotationHelper;
		this.reminderService = reminderService;
		panelComponent.setBorder(new Rectangle(8, 8, 8, 8));
		panelComponent.setGap(new Point(0, 4));
		panelComponent.setPreferredSize(SIZE);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Jam's Arceuus Runecrafting");
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset session & totals", "Jam's Arceuus Runecrafting",
			e -> rotationHelper.resetAllCounters());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showStatusPanel())
		{
			return null;
		}

		HelperAction action = rotationHelper.getCurrentAction();
		boolean inRotation = config.enableHelper()
			&& action != null
			&& action.getStep() != RotationStep.IDLE;
		List<String> warnings = reminderService.getWarnings();
		if (!inRotation && warnings.isEmpty())
		{
			return null;
		}

		RcMode mode = rotationHelper.getResolvedMode();
		InventorySnapshot inv = rotationHelper.getSnapshot();

		panelComponent.getChildren().add(LineComponent.builder()
			.left(mode == RcMode.SOUL ? "Souls" : "Bloods")
			.leftColor(mode.getColor())
			.build());

		if (inRotation)
		{
			Color stepColor = action.getColor() != null ? action.getColor() : Color.WHITE;
			panelComponent.getChildren().add(line("Next", action.getStep().getLabel(), stepColor));
			String detail = action.getDetail();
			if (detail != null && !detail.isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(detail)
					.leftColor(DETAIL)
					.leftFont(FontManager.getRunescapeSmallFont())
					.build());
			}
		}

		if (inv != null)
		{
			if (mode == RcMode.BLOOD && config.bloodEssenceReminder())
			{
				panelComponent.getChildren().add(line("Essence", essenceText(inv), essenceColor(inv)));
			}

			addStatsSection();
		}

		for (String warning : warnings)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(warning)
				.leftColor(WARN)
				.build());
		}

		return super.render(graphics);
	}

	private void addStatsSection()
	{
		if (!config.showStats())
		{
			return;
		}

		StatsScope scope = config.statsScope();
		boolean showTrips = config.showTrips();
		boolean showRuneCounts = config.showRuneCounts();
		if (!showTrips && !showRuneCounts)
		{
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder().left("").build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Stats (" + scope.panelSuffix() + ")")
			.leftColor(LABEL)
			.build());

		if (showTrips)
		{
			panelComponent.getChildren().add(line(
				"Trips",
				scope.format(rotationHelper.getTripsCompleted(), rotationHelper.getTotalTrips()),
				LABEL));
		}
		if (showRuneCounts)
		{
			if (rotationHelper.getResolvedMode() == RcMode.SOUL)
			{
				panelComponent.getChildren().add(line(
					"Souls",
					scope.format(rotationHelper.getSoulRunesCrafted(), rotationHelper.getTotalSoulRunes()),
					LABEL));
			}
			else
			{
				panelComponent.getChildren().add(line(
					"Bloods",
					scope.format(rotationHelper.getBloodRunesCrafted(), rotationHelper.getTotalBloodRunes()),
					LABEL));
			}
		}
	}

	private static LineComponent line(String left, String right, Color rightColor)
	{
		return LineComponent.builder()
			.left(left)
			.leftColor(LABEL)
			.right(right)
			.rightColor(rightColor)
			.build();
	}

	private String essenceText(InventorySnapshot inv)
	{
		if (inv.isHasActiveBloodEssence())
		{
			Integer charges = reminderService.getBloodEssenceCharges();
			if (charges != null)
			{
				return charges + " charges";
			}
			return "active";
		}
		if (inv.isHasInactiveBloodEssence())
		{
			return "activate";
		}
		return "need one";
	}

	private Color essenceColor(InventorySnapshot inv)
	{
		if (inv.isHasActiveBloodEssence())
		{
			Integer charges = reminderService.getBloodEssenceCharges();
			if (charges != null && charges <= config.bloodEssenceLowCharges())
			{
				return WARN;
			}
			return ESSENCE_OK;
		}
		return WARN;
	}
}

package com.zeahrchelper;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AgilityShortcutTest
{
	@Test
	public void hopBetweenMatchesAllShortcutsIncludingReverse52AndTiny69()
	{
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.BOULDER_49.getFrom(), AgilityShortcut.BOULDER_49.getTo()));
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.EAST_52.getFrom(), AgilityShortcut.EAST_52.getTo()));
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.EAST_52.getTo(), AgilityShortcut.EAST_52.getFrom()));
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.NORTH_69.getFrom(), AgilityShortcut.NORTH_69.getTo()));
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.NORTH_69.getTo(), AgilityShortcut.NORTH_69.getFrom()));
		assertTrue(AgilityShortcut.hopBetween(
			AgilityShortcut.WEST_73.getFrom(), AgilityShortcut.WEST_73.getTo()));
	}

	@Test
	public void oneWayShortcutsAreNotReversible()
	{
		assertFalse(AgilityShortcut.hopBetween(
			AgilityShortcut.BOULDER_49.getTo(), AgilityShortcut.BOULDER_49.getFrom()));
		assertFalse(AgilityShortcut.hopBetween(
			AgilityShortcut.WEST_73.getTo(), AgilityShortcut.WEST_73.getFrom()));
	}

	@Test
	public void objectIdFollows52Direction()
	{
		assertEquals(
			ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_BOTTOM,
			AgilityShortcut.objectIdForHop(AgilityShortcut.EAST_52.getFrom(), AgilityShortcut.EAST_52.getTo()));
		assertEquals(
			ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_MIDGREY_TOP,
			AgilityShortcut.objectIdForHop(AgilityShortcut.EAST_52.getTo(), AgilityShortcut.EAST_52.getFrom()));
		assertEquals(
			AgilityShortcut.NORTH_OBJECT_ID,
			AgilityShortcut.objectIdForHop(AgilityShortcut.NORTH_69.getFrom(), AgilityShortcut.NORTH_69.getTo()));
	}

	@Test
	public void firstHopSkipsHopsAlreadyBehindThePlayer()
	{
		WorldPoint before = new WorldPoint(1776, 3888, 0);
		WorldPoint afterBoulder = new WorldPoint(1776, 3878, 0);
		WorldPoint before69 = new WorldPoint(1761, 3870, 0);
		List<WorldPoint> path = Arrays.asList(
			before,
			AgilityShortcut.BOULDER_49.getFrom(),
			AgilityShortcut.BOULDER_49.getTo(),
			afterBoulder,
			before69,
			AgilityShortcut.NORTH_69.getFrom(),
			AgilityShortcut.NORTH_69.getTo());

		AgilityShortcut.Hop first = AgilityShortcut.firstHop(path);
		assertNotNull(first);
		assertEquals(AgilityShortcut.BOULDER_49.getFrom(), first.getFrom());

		AgilityShortcut.Hop remaining = AgilityShortcut.firstHop(path, afterBoulder);
		assertNotNull(remaining);
		assertEquals(AgilityShortcut.NORTH_69.getFrom(), remaining.getFrom());
		assertEquals(AgilityShortcut.NORTH_69.getTo(), remaining.getTo());
	}

	@Test
	public void craftAtBloodAltarDoesNotEnable73()
	{
		WorldPoint blood = ZeahRcArea.BLOOD_ALTAR;
		assertFalse(AgilityShortcut.WEST_73.enabled(99, RotationStep.CRAFT_FRAGMENTS, blood, RcMode.BLOOD, false));
		assertFalse(AgilityShortcut.WEST_73.enabled(99, RotationStep.CHISEL_AT_ALTAR, blood, RcMode.BLOOD, false));
		assertFalse(AgilityShortcut.WEST_73.enabled(99, RotationStep.CRAFT_REMAINING, blood, RcMode.BLOOD, false));
		assertTrue(AgilityShortcut.WEST_73.enabled(99, RotationStep.RETURN_TO_MINE, blood, RcMode.BLOOD, false));
	}

	@Test
	public void goAltarDoesNotEnable69Or73Or49()
	{
		WorldPoint dark = ZeahRcArea.DARK_ALTAR;
		WorldPoint soulApproach = new WorldPoint(1786, 3895, 0);
		WorldPoint blood = ZeahRcArea.BLOOD_ALTAR;

		assertFalse(AgilityShortcut.NORTH_69.enabled(99, RotationStep.GO_ALTAR, dark, RcMode.BLOOD, false));
		assertFalse(AgilityShortcut.WEST_73.enabled(99, RotationStep.GO_ALTAR, blood, RcMode.BLOOD, false));
		assertFalse(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.GO_ALTAR, soulApproach, RcMode.SOUL, false));
	}

	@Test
	public void boulderStaysEnabledOnTheStandTileAndNorthRidge()
	{
		WorldPoint stand = AgilityShortcut.BOULDER_49.getFrom();
		WorldPoint justWest = new WorldPoint(1774, 3886, 0);
		WorldPoint soulAltar = ZeahRcArea.SOUL_ALTAR;
		WorldPoint landed = AgilityShortcut.BOULDER_49.getTo();
		WorldPoint mine = ZeahRcArea.MINE_STAND;

		assertTrue(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.RETURN_TO_MINE, stand, RcMode.SOUL, false));
		assertTrue(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.RETURN_TO_MINE, justWest, RcMode.SOUL, false));
		assertTrue(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.RETURN_TO_MINE, soulAltar, RcMode.SOUL, false));
		assertFalse(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.RETURN_TO_MINE, landed, RcMode.SOUL, false));
		assertFalse(AgilityShortcut.BOULDER_49.enabled(99, RotationStep.RETURN_TO_MINE, mine, RcMode.SOUL, true));
	}

	@Test
	public void east52DisabledOnBloodWestCorridorAndEnabledFromMineOnSoul()
	{
		WorldPoint dark = ZeahRcArea.DARK_ALTAR;
		WorldPoint mine = ZeahRcArea.MINE_STAND;
		assertFalse(AgilityShortcut.EAST_52.enabled(99, RotationStep.GO_ALTAR, dark, RcMode.BLOOD, false));
		assertTrue(AgilityShortcut.EAST_52.enabled(99, RotationStep.GO_ALTAR, mine, RcMode.SOUL, true));
	}
}

package com.zeahrchelper;

import net.runelite.api.coords.WorldPoint;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class BloodAltarReachTest
{
	private static final WorldPoint MINE_EDGE_IN = new WorldPoint(1765, 3855, 0);
	private static final WorldPoint MINE_EDGE_OUT = new WorldPoint(1766, 3855, 0);
	private static final WorldPoint SOUTH_OF_DARK_ALTAR = ZeahRcArea.DARK_APPROACH;
	private static final WorldPoint ONE_TILE_SHORT = new WorldPoint(1723, 3879, 0);
	private static final WorldPoint DARK_ALTAR = ZeahRcArea.DARK_ALTAR;

	@Test
	public void reachIsMeasuredToTheNearestFootprintTile()
	{
		assertEquals(46, BloodAltarReach.reachTo(MINE_EDGE_IN));
		assertEquals(46, BloodAltarReach.reachTo(SOUTH_OF_DARK_ALTAR));
		assertEquals(47, BloodAltarReach.reachTo(MINE_EDGE_OUT));
		assertEquals(47, BloodAltarReach.reachTo(ONE_TILE_SHORT));
		assertEquals(50, BloodAltarReach.reachTo(DARK_ALTAR));
		assertEquals(0, BloodAltarReach.reachTo(ZeahRcArea.BLOOD_ALTAR));
	}

	@Test
	public void goAltarReadyWhenInReachAndLoaded()
	{
		assertEquals(BloodAltarReach.State.READY, at(SOUTH_OF_DARK_ALTAR, true));
		assertEquals(BloodAltarReach.State.READY, at(MINE_EDGE_IN, true));
	}

	@Test
	public void goAltarStandThenClickWhenOutsideReach()
	{
		assertEquals(BloodAltarReach.State.STAND_THEN_CLICK, at(ONE_TILE_SHORT, true));
		assertEquals(BloodAltarReach.State.STAND_THEN_CLICK, at(DARK_ALTAR, true));
	}

	@Test
	public void goAltarReadyAfterAltarClickEvenOutsideReach()
	{
		assertEquals(BloodAltarReach.State.READY,
			BloodAltarReach.evaluate(RotationStep.GO_ALTAR, RcMode.BLOOD, DARK_ALTAR, true, true));
	}

	@Test
	public void goAltarWalkWhenAltarNotLoaded()
	{
		assertEquals(BloodAltarReach.State.WALK, at(SOUTH_OF_DARK_ALTAR, false));
	}

	@Test
	public void otherStepsAndSoulsDoNotApply()
	{
		assertEquals(BloodAltarReach.State.NONE,
			BloodAltarReach.evaluate(RotationStep.GO_DARK_SECOND, RcMode.BLOOD, DARK_ALTAR, true));
		assertEquals(BloodAltarReach.State.NONE,
			BloodAltarReach.evaluate(RotationStep.GO_ALTAR, RcMode.SOUL, SOUTH_OF_DARK_ALTAR, true));
		assertEquals(BloodAltarReach.State.NONE,
			BloodAltarReach.evaluate(RotationStep.GO_ALTAR, RcMode.BLOOD, null, true));
	}

	private static BloodAltarReach.State at(WorldPoint tile, boolean altarInScene)
	{
		return BloodAltarReach.evaluate(RotationStep.GO_ALTAR, RcMode.BLOOD, tile, altarInScene);
	}
}

